import { craftAppConfig, ɵsignal as signal } from '@craft-ts/core';

const params = new URLSearchParams(location.search);
const count = Number(params.get('rows') ?? 1000);
const variant = params.get('case') ?? 'rows';
const instrument = params.get('counts') === 'true';
const reads = { a: 0, b: 0 };
const rows = signal(
  Array.from({ length: count }, (_, id) => ({ id, label: `Row ${id}` })),
);
const revision = signal(0);
const values = Array.from({ length: 128 }, (_, i) => signal(`Field ${i}`));
const read = (index: number) => {
  if (instrument) reads[index === 0 ? 'a' : 'b']++;
  return values[index]();
};
const Row=craftComponent('CompilerBenchRow',{},(inputs:{row:Input<{id:number;label:string}>;position:Input<number>})=>div({attrs:{role:'row',"data-column-0":"column-0","data-column-1":"column-1","data-column-2":"column-2","data-column-3":"column-3","data-column-4":"column-4","data-column-5":"column-5","data-column-6":"column-6","data-column-7":"column-7"},'data-row':function*(){return (yield* inputs.row()).id;}},function*(){return (yield* inputs.row()).label;}));
const IndexedRow = craftComponent(
  'CompilerBenchIndexedRow',
  {},
  (inputs: {
    row: Input<{ id: number; label: string }>;
    position: Input<number>;
  }) =>
    div(
      {
