    // renderer runs the template once: only declarations precede the return.
    const setup: string[] = [];
    if (ts.isBlock(fn.body)) {
      const statements = fn.body.statements;
      const last = statements[statements.length - 1];
      if (
        !last ||
        !ts.isReturnStatement(last) ||
        !last.expression ||
