type YieldHelper<
  Name extends string,
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
  AppStart extends boolean = false,
  ProvidedInput = ServiceProvidedInput<Inputs>,
  ProvideArgs extends unknown[] = ProvideArguments<ProvidedInput>,
> = {
  [Key in Capitalize<Name>]: WithTrackedDependencies<
    WithServiceRuntimeMeta<
      {
        (): Generator<
          ServiceYieldRequest<
            Scope,
            MaybeErrorOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >,
            Metadata,
            Uncapitalize<Name>,
            MaybeErrorOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >
          >,
          MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, undefined, Output>,
          unknown
        >;
        <Config extends Partial<PublicInputBindings<Inputs, Scope>>>(
          bindings: StrictBindings<
            Partial<PublicInputBindings<Inputs, Scope>>,
            Config
          >,
        ): Generator<
          ServiceYieldRequest<
            Scope,
            MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
            Metadata,
            Uncapitalize<Name>,
            MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>
          >,
          MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
          unknown
        >;
        <
          Exposed extends object,
          Yielded extends ExposureYield<
            SelectableOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >
          > = never,
        >(
          bindings: undefined,
          expose: ExposureSelector<
            SelectableOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >,
            Exposed,
            Yielded
          >,
        ): Generator<
          | ServiceYieldRequest<
              Scope,
              SelectableOutput<
                ServiceCallInputs<Scope, Inputs>,
                undefined,
                Output
              >,
              WithDerivedProperties<Metadata, Exposed, Yielded>
            >
          | ExposureYield<
              SelectableOutput<
                ServiceCallInputs<Scope, Inputs>,
                undefined,
                Output
              >
            >,
          ExposedOutput<
            SelectableOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >,
            MaterializeExposureResult<ValidateRootExposure<Exposed>>
          >,
          unknown
        >;
        <
          Config extends Partial<PublicInputBindings<Inputs, Scope>>,
          Exposed extends object,
          Yielded extends ExposureYield<
            SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>
          > = never,
        >(
          bindings: StrictBindings<
            Partial<PublicInputBindings<Inputs, Scope>>,
            Config
          >,
          expose: ExposureSelector<
            SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
            Exposed,
            Yielded
          >,
        ): Generator<
          | ServiceYieldRequest<
              Scope,
              SelectableOutput<
                ServiceCallInputs<Scope, Inputs>,
                Config,
                Output
              >,
              WithDerivedProperties<Metadata, Exposed, Yielded>
            >
          | ExposureYield<
              SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>
            >,
          ExposedOutput<
            SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
            MaterializeExposureResult<ValidateRootExposure<Exposed>>
          >,
          unknown
        >;
      } & YieldPropertyShortcuts<Scope, Inputs, Output, Metadata> &
        (keyof ServiceCallInputs<Scope, Inputs> extends never
          ? {}
          : {
              OmitInputs: OmitInputsYieldShortcuts<
                Scope,
                Inputs,
                Output,
                Metadata
              >;
            }),
      ServiceRuntimeMetaDefinition<
        Name,
        Scope,
        Inputs,
        Output,
        Metadata,
        AppStart,
        ProvidedInput,
        ProvideArgs
      >
    >,
    Metadata
  >;
};

type ExtractServiceTrackingYielded<Metadata> =
  Metadata extends ServiceTrackingMetadata<
    any,
    any,
    any,
    infer Yielded,
    any,
    any,
    any,
    any
  >
    ? Yielded
    : never;

type ProvideHelper<
  Name extends string,
  Scope extends RealCapableScope,
  Output,
  ProvideArgs extends unknown[],
  Yielded = never,
> = {
  [Key in `provide${Capitalize<Name>}`]: (
    ...args: ProvideArgs
  ) => NamedBrandedServiceProvider<Name, Scope, Output, Yielded>;
};

type RequirementHelper<Name extends string, Contract> = {
  [Key in `${Capitalize<Name>}Requirement`]: ServiceRequirement<Contract, Name>;
};

type ServiceMetaDataHelper<
  Name extends string,
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
  AppStart extends boolean = false,
  ProvidedInput = ServiceProvidedInput<Inputs>,
  ProvideArgs extends unknown[] = ProvideArguments<ProvidedInput>,
> = {
  [Key in ServiceMetaDataKey<Name>]: ServiceMetaData<
    Name,
    Scope,
    ServiceCallInputs<Scope, Inputs>,
    Output,
    ResolveServiceTrackingMetadata<Metadata>,
    ExtractHelperValue<
      InjectHelper<
        Name,
        Scope,
        Inputs,
        Output,
        Metadata,
        AppStart,
        ProvidedInput,
        ProvideArgs
      >
    >,
    Metadata,
    ProvidedInput,
    ProvideArgs,
    TrackingBrowserBoundary<Metadata>,
    AppStart
  >;
};

type ConcreteServiceApi<
  Name extends string,
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
  AppStart extends boolean = false,
> = YieldHelper<Name, Scope, Inputs, Output, Metadata, AppStart> &
  ServiceMetaDataHelper<Name, Scope, Inputs, Output, Metadata, AppStart> &
  (Scope extends 'toProvide' | 'manuallyProvidedAtRoot'
    ? ProvideHelper<
        Name,
        Extract<Scope, RealCapableScope>,
        Output,
        ProvideArguments<ServiceProvidedInput<Inputs>>,
        ExtractServiceTrackingYielded<Metadata>
      >
    : {}) & {};

export type CraftServiceApi<
  Name extends string,
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata = ServiceTrackingMetadata<
    Name,
    Scope,
    Output,
    never
  >,
  AppStart extends boolean = false,
> = ConcreteServiceApi<Name, Scope, Inputs, Output, Metadata, AppStart>;

type AbstractProvideFactory<Contract> =
  | (() => Contract)
  | (() => Generator<any, Contract, any>);

type AbstractProvideHelper<Name extends string, Contract> = {
  [Key in `provide${Capitalize<Name>}`]: <
    Factory extends AbstractProvideFactory<Contract>,
  >(
    factory: Factory,
  ) => NamedBrandedServiceProvider<
    Name,
    'toProvide',
    Contract,
    FactoryYields<Factory>
  >;
};

type AbstractHelper<Name extends string, Contract> = {
  [Key in Capitalize<Name>]: () => Generator<
    ServiceYieldRequest<
      'toProvide',
      Contract,
      ServiceTrackingMetadata<Name, 'toProvide', Contract, never>
    >,
    Contract,
    unknown
  >;
};

export type AbstractServiceApi<
  Name extends string,
  Contract,
> = RequirementHelper<Name, Contract> &
  AbstractProvideHelper<Name, Contract> &
  AbstractHelper<Name, Contract>;

type ConcreteRuntimeDefinition = {
  factory: AnyFactory;
  name: string;
  providedIn: ConcreteServiceScope;
  browserBoundary: boolean;
  appStart: boolean;
  providers?: readonly Provider[];
  collection: boolean;
  token?: object;
  requirement?: ServiceRequirement<unknown>;
  initialBindings?: Record<string, unknown>;
  hasPublicInput: boolean;
  hasProvidedInput: boolean;
  appStartHooks: Map<unknown, () => AppStartResult>;
  startedAppStartServices: Set<unknown>;
  /** `'auto'` exposes yielded primitives; `'value'` exposes the factory result. */
  exposure: ServiceExposure;
};

type ServiceExposure = 'auto' | 'value';

const OMIT_INPUTS_BINDINGS = Symbol('craft-ts.omit-inputs-bindings');
type ConcreteServiceBindings =
  | Record<string, unknown>
  | typeof OMIT_INPUTS_BINDINGS;

function wrapOmitInputsHelper(value: unknown): unknown {
  if (typeof value !== 'function') return value;

  return new Proxy(value as (...args: unknown[]) => unknown, {
    get(target, property, receiver) {
      const nested = Reflect.get(target, property, receiver);
      return typeof nested === 'function'
        ? wrapOmitInputsHelper(nested)
        : nested;
    },
    apply(target, thisArg, args) {
      return Reflect.apply(target, thisArg, [OMIT_INPUTS_BINDINGS, ...args]);
    },
  });
}

export type ServiceReference<
