  output: Output;
  yielded: Yielded;
  derived: Derived;
  providedInput: ProvidedInput;
  browserBoundary: BrowserBoundary;
  appStart: AppStart;
};

type AnyServiceTrackingMetadata = ServiceTrackingMetadata<
  string,
  ConcreteServiceScope,
  unknown,
  unknown,
  any,
  any,
  boolean,
  boolean
>;

type WithServiceNodeFlags<
  Derived,
  BrowserBoundary extends boolean,
  AppStart extends boolean,
> = Simplify<
  {
    browserBoundary: BrowserBoundary;
    appStart: AppStart;
  } & ([Derived] extends [undefined] ? {} : Derived)
>;

type TrackingBrowserBoundary<Metadata> =
  Metadata extends ServiceTrackingMetadata<
    any,
    any,
    any,
    any,
    any,
    any,
    infer BrowserBoundary extends boolean,
    any
  >
    ? BrowserBoundary
    : false;

type DependencyBrowserBoundary<Node> = Node extends {
  browserBoundary: infer BrowserBoundary extends boolean;
}
  ? BrowserBoundary
  : false;

type DependencyAppStart<Node> = Node extends {
  appStart: infer AppStart extends boolean;
}
  ? AppStart
  : false;

type OrBoolean<Left extends boolean, Right extends boolean> = true extends
  | Left
  | Right
  ? true
  : false;

type WholeServiceUsageTracking = {
  usesWholeService: true;
};

type DirectDependencyRequestUnion<Yielded> = Extract<
  Yielded,
  ServiceYieldRequest<any, any, any, any, any>
>;

type AppStartDependencyRequestUnion<Yielded> =
  Extract<Yielded, ServiceAppStartRequest<any>> extends infer Request
    ? Request extends ServiceAppStartRequest<infer AppStartYielded>
      ? Extract<AppStartYielded, ServiceYieldRequest<any, any, any, any, any>>
      : never
    : never;

type DependencyRequests<Yielded> = UnionToTuple<
  | DirectDependencyRequestUnion<Yielded>
  | AppStartDependencyRequestUnion<Yielded>
>;

type DependencyMetadata<Request> =
  Request extends ServiceYieldRequest<any, any, infer Metadata, any, any>
    ? Metadata
    : never;

type DependencyName<Request> =
  DependencyMetadata<Request> extends ServiceTrackingMetadata<
    infer Name,
    any,
    any,
    any,
    any,
    any,
    any,
    any
  >
    ? Name
    : never;

type NodeDerivedProperties<Node> = Node extends {
  derivedPropertiesUsed: infer Used extends object;
  derivedPropertiesExposed: infer Exposed extends object;
}
  ? DerivedPropertiesTracking<Used, Exposed>
  : undefined;

type MergeDerivedProperties<Left, Right> = [Left] extends [
  DerivedPropertiesTracking<infer LeftUsed, infer LeftExposed>,
]
  ? [Right] extends [
      DerivedPropertiesTracking<infer RightUsed, infer RightExposed>,
    ]
    ? DerivedPropertiesTracking<
        Simplify<LeftUsed & RightUsed>,
        Simplify<LeftExposed & RightExposed>
      >
    : undefined
  : undefined;

type DependencyChildren<Node> = Node extends {
  dependencies: infer Dependencies extends object;
}
  ? Dependencies
  : {};

type DependencyScope<Node> = Node extends { providedIn: infer Scope }
  ? Scope
  : never;

type MergeDependencyNodeMaps<
  Left extends object,
  Right extends object,
> = Simplify<{
  [Name in Extract<keyof Left | keyof Right, string>]: Name extends keyof Left
    ? Name extends keyof Right
      ? MergeDependencyNodes<Left[Name], Right[Name]>
      : Left[Name]
    : Name extends keyof Right
      ? Right[Name]
      : never;
}>;

type MergeDependencyNodes<Left, Right> = ServiceDependencies<
  DependencyScope<Left> & DependencyScope<Right>,
  MergeDependencyNodeMaps<DependencyChildren<Left>, DependencyChildren<Right>>,
  WithServiceNodeFlags<
    MergeDerivedProperties<
      NodeDerivedProperties<Left>,
      NodeDerivedProperties<Right>
    >,
    DependencyBrowserBoundary<Left> & DependencyBrowserBoundary<Right>,
    OrBoolean<DependencyAppStart<Left>, DependencyAppStart<Right>>
  >
>;

// Dependency maps carried by primitives consumed through `yield*`. A primitive
// generator surfaces its already-built dependency map (keyed by service name) on
// `ServiceTrackedDepsRequest`; these are folded into the host service tree so
// dependencies used only inside loaders/effects are detected.
// An empty dep map has to leave the union BEFORE it is formed: `{} | Map`
// reduces to `{}` (every object type is assignable to it), which would erase
// every sibling map — a service mixing a dependency-free primitive with a
// dependency-carrying one would silently lose the latter.
type TrackedDepMapOf<Request> =
  Request extends ServiceTrackedDepsRequest<infer DepMap>
    ? [DepMap] extends [never]
      ? never
      : [keyof DepMap] extends [never]
        ? never
        : DepMap
    : never;

type AppStartYieldedOf<Request> =
  Request extends ServiceAppStartRequest<infer AppStartYielded>
    ? AppStartYielded
    : never;

type TrackedDepMapUnion<Yielded> =
  | TrackedDepMapOf<Extract<Yielded, ServiceTrackedDepsRequest<any>>>
  | TrackedDepMapOf<
      Extract<
        AppStartYieldedOf<Extract<Yielded, ServiceAppStartRequest<any>>>,
        ServiceTrackedDepsRequest<any>
      >
    >;

type MergeAllDependencyNodeMaps<
  Maps extends object[],
  Accumulator extends object = {},
> = Maps extends [infer First extends object, ...infer Rest extends object[]]
  ? MergeAllDependencyNodeMaps<
      Rest,
      MergeDependencyNodeMaps<Accumulator, First>
    >
  : Accumulator;

type TrackedDepsMapFromYielded<Yielded> = MergeAllDependencyNodeMaps<
  UnionToTuple<TrackedDepMapUnion<Yielded>> extends infer Tuple extends object[]
    ? Tuple
    : []
>;

type ResolveServiceTrackingMetadata<Metadata> =
  Metadata extends ServiceTrackingMetadata<
    infer Name extends string,
    infer Scope extends ConcreteServiceScope,
    infer Output,
    infer Yielded,
    infer Derived,
    any,
    infer BrowserBoundary extends boolean,
    infer AppStart extends boolean
  >
    ? ServiceDependencies<
        Scope,
        MergeDependencyNodeMaps<
          BuildDependencyMap<DependencyRequests<Yielded>>,
          TrackedDepsMapFromYielded<Yielded>
        >,
        WithServiceNodeFlags<Derived, BrowserBoundary, AppStart>
      >
    : never;

export type ExtractServiceHelperDependencies<ServiceHelper> =
  ResolveServiceTrackingMetadata<ExtractTrackedMetadata<ServiceHelper>>;

export type ExtractServiceHelperDependencyMap<ServiceHelper> =
  ExtractTrackedMetadata<ServiceHelper> extends ServiceTrackingMetadata<
    infer Name extends string,
    ConcreteServiceScope,
    unknown,
    unknown,
    unknown,
    unknown,
    boolean,
    boolean
  >
    ? {
        [Key in Name]: ExtractServiceHelperDependencies<ServiceHelper>;
      }
    : never;

/**
 * The dependency a value carries because it *is* a service helper — the
 * shortcut `Service.member` handed to a template binding.
 *
 * The carrier is optional, so `extends { [SERVICE_HELPER_DEPENDENCIES]?: … }`
 * alone would match every type and answer with the constraint. The `keyof`
 * guard is what makes the question "does this value carry the brand?".
 */
export type ServiceHelperDependencyMapOf<Value> =
  typeof SERVICE_HELPER_DEPENDENCIES extends keyof Value
    ? ExtractServiceHelperDependencyMap<Value>
    : {};

export type ServiceDependencyMapFromYielded<Yielded> = BuildDependencyMap<
  DependencyRequests<Yielded>
>;

type DependencyMapFromValue<Value> = Value extends {
  readonly [SERVICE_HELPER_DEPENDENCIES]?: infer Dependencies extends object;
}
  ? Dependencies
  : {};

type DependencyValues<Values> = Values extends object
  ? Values[keyof Values]
  : Values;

type DependencyMapsFromValues<Values> = DependencyMapFromValue<
  DependencyValues<Values>
>;

/**
 * Extracts and merges dependency metadata carried by insertion outputs.
 *
 * `on$` uses this carrier because subscribing to a source is a consumer-side
 * dependency, while emitting a source value is only a producer operation.
 */
export type ServiceDependencyMapFromValues<Values> = MergeAllDependencyNodeMaps<
  [Values] extends [never]
    ? []
    : UnionToTuple<DependencyMapsFromValues<Values>> extends infer Tuple
      ? Tuple extends object[]
        ? Tuple
        : []
      : []
>;

export type MergeServiceDependencyMaps<
  Left extends object,
  Right extends object,
> = MergeDependencyNodeMaps<Left, Right>;

export type ServiceDependencyMapFromYieldedAndValues<Yielded, Values> =
  MergeServiceDependencyMaps<
    ServiceDependencyMapFromYielded<Yielded>,
    ServiceDependencyMapFromValues<Values>
  >;

export type CompleteServiceDependencyMapFromYielded<Yielded> =
  MergeDependencyNodeMaps<
    ServiceDependencyMapFromYielded<Yielded>,
    TrackedDepsMapFromYielded<Yielded>
  >;

type DependencyDefinition<Request> = ResolveServiceTrackingMetadata<
  DependencyMetadata<Request>
>;

type DependencyRecord<Request> =
  DependencyMetadata<Request> extends ServiceTrackingMetadata<
    infer Name extends string,
    any,
    any,
    any,
    any,
    any,
    any,
    any
  >
    ? // Some yield requests (e.g. raw injector helpers like `HostTag`)
      // are structurally compatible with `ServiceYieldRequest<any, any, any>`
      // but carry no explicit metadata, so `Name` widens to `string`. Without
      // this guard, `[Key in string]` would emit an index signature that
      // corrupts the merged deps map for every other entry.
      string extends Name
      ? {}
      : { [Key in Name]: DependencyDefinition<Request> }
    : {};

type BuildDependencyMap<
  Requests extends unknown[],
  Accumulator extends object = {},
> = Requests extends [infer First, ...infer Rest]
  ? BuildDependencyMap<
      Rest,
      MergeDependencyNodeMaps<Accumulator, DependencyRecord<First>>
    >
  : Simplify<Accumulator>;

type NormalizeWholeServiceUsage<Derived> = [Derived] extends [undefined]
  ? WholeServiceUsageTracking
  : Derived;

type TrackedNodeUsage<Node> = Node extends { usesWholeService: true }
  ? WholeServiceUsageTracking
  : NodeDerivedProperties<Node>;

type MergeTrackedDependencyUsage<Left, Right> =
  Left extends WholeServiceUsageTracking
    ? WholeServiceUsageTracking
    : Right extends WholeServiceUsageTracking
      ? WholeServiceUsageTracking
      : [Left] extends [
            DerivedPropertiesTracking<infer LeftUsed, infer LeftExposed>,
          ]
        ? [Right] extends [
            DerivedPropertiesTracking<infer RightUsed, infer RightExposed>,
          ]
          ? DerivedPropertiesTracking<
              Simplify<LeftUsed & RightUsed>,
              Simplify<LeftExposed & RightExposed>
            >
          : WholeServiceUsageTracking
        : WholeServiceUsageTracking;

type MergeTrackedDependencyNodes<Left, Right> = Simplify<
  {
    providedIn: DependencyScope<Left> & DependencyScope<Right>;
    dependencies: MergeTrackedDependencyNodeMaps<
      DependencyChildren<Left>,
      DependencyChildren<Right>
    >;
  } & WithServiceNodeFlags<
    MergeTrackedDependencyUsage<
      TrackedNodeUsage<Left>,
      TrackedNodeUsage<Right>
    >,
    DependencyBrowserBoundary<Left> & DependencyBrowserBoundary<Right>,
    OrBoolean<DependencyAppStart<Left>, DependencyAppStart<Right>>
  >
>;

type MergeTrackedDependencyNodeMaps<
  Left extends object,
  Right extends object,
> = Simplify<{
  [Name in Extract<keyof Left | keyof Right, string>]: Name extends keyof Left
    ? Name extends keyof Right
      ? MergeTrackedDependencyNodes<Left[Name], Right[Name]>
      : Left[Name]
    : Name extends keyof Right
      ? Right[Name]
      : never;
}>;

type ResolveTrackedDependencyMetadata<Metadata> =
  Metadata extends ServiceTrackingMetadata<
    infer Name extends string,
    infer Scope extends ConcreteServiceScope,
    infer Output,
    infer Yielded,
    infer Derived,
    any,
    infer BrowserBoundary extends boolean,
    infer AppStart extends boolean
  >
    ? Simplify<
        {
          providedIn: Scope;
          dependencies: BuildTrackedDependencyMap<DependencyRequests<Yielded>>;
        } & WithServiceNodeFlags<
          NormalizeWholeServiceUsage<Derived>,
          BrowserBoundary,
          AppStart
        >
      >
    : never;

type TrackedDependencyRecord<Request> =
  DependencyMetadata<Request> extends ServiceTrackingMetadata<
    infer Name extends string,
    any,
    any,
    any,
    any,
    any,
    any,
    any
  >
    ? {
        [Key in Name]: ResolveTrackedDependencyMetadata<
          DependencyMetadata<Request>
        >;
      }
    : {};

type BuildTrackedDependencyMap<
  Requests extends unknown[],
  Accumulator extends object = {},
> = Requests extends [infer First, ...infer Rest]
  ? BuildTrackedDependencyMap<
      Rest,
      MergeTrackedDependencyNodeMaps<
        Accumulator,
        TrackedDependencyRecord<First>
      >
    >
  : Simplify<Accumulator>;

type FlattenTrackedDependencyNodeMapFromTracking<Tracking> =
  Tracking extends ServiceTrackingMetadata<
    any,
    any,
    any,
    infer Yielded,
    any,
    any,
    any,
    any
  >
    ? BuildFlattenedTrackedDependencyNodeMap<DependencyRequests<Yielded>>
    : {};

type BuildFlattenedTrackedDependencyNodeMap<
  Requests extends unknown[],
  Accumulator extends object = {},
> = Requests extends [infer First, ...infer Rest]
  ? BuildFlattenedTrackedDependencyNodeMap<
      Rest,
      MergeTrackedDependencyNodeMaps<
        MergeTrackedDependencyNodeMaps<
          Accumulator,
          TrackedDependencyRecord<First>
        >,
        FlattenTrackedDependencyNodeMapFromTracking<DependencyMetadata<First>>
      >
    >
  : Simplify<Accumulator>;

type ServiceHelperMetadata<
  Name extends string,
  Scope extends ConcreteServiceScope,
  Factory extends AnyFactory,
  BrowserBoundary extends boolean = false,
  AppStart extends boolean = false,
  Output = FactoryOutput<Factory>,
> = ServiceTrackingMetadata<
  Name,
  Scope,
  Output,
  FactoryYields<Factory>,
  undefined,
  ServiceProvidedInput<FactoryInputs<Factory>>,
  BrowserBoundary,
  AppStart
>;

type WithDerivedProperties<
  Metadata extends AnyServiceTrackingMetadata,
  Exposed extends object,
  Yielded,
> =
  Metadata extends ServiceTrackingMetadata<
    infer Name extends string,
    infer Scope extends ConcreteServiceScope,
    infer Output,
    infer ChildYielded,
    any,
    infer ProvidedInput,
    infer BrowserBoundary extends boolean,
    infer AppStart extends boolean
  >
    ? ServiceTrackingMetadata<
        Name,
        Scope,
        Output,
        ChildYielded,
        DerivedPropertiesForExposure<Exposed, Yielded>,
        ProvidedInput,
        BrowserBoundary,
        AppStart
      >
    : never;

export type ServiceYieldRequest<
  Scope extends ConcreteServiceScope,
  Result,
  Metadata extends AnyServiceTrackingMetadata = AnyServiceTrackingMetadata,
  ExposureName extends string = never,
  Exposure = unknown,
> = Readonly<{
  [SERVICE_YIELD_REQUEST_MARKER]: true;
  name: string;
  readonly exposure?: [ExposureName] extends [never]
    ? never
    : {
        readonly name: ExposureName;
        readonly internal?: boolean;
        readonly value?: Exposure;
        readonly resolve?: any;
      };
  readonly [SERVICE_YIELD_METADATA]?: Metadata;
  providedIn: Scope;
  resolve: (injector: Injector, hostScope: ConcreteServiceScope) => Result;
}>;

type ServiceYieldExposure<Yielded> = [Yielded] extends [never]
  ? {}
  : Yielded extends ServiceYieldRequest<
        any,
        any,
        any,
        infer ExposureName,
        infer ExposureValue
      >
    ? [ExposureName] extends [never]
      ? {}
      : string extends ExposureName
        ? {}
        : ExposureName extends string
          ? { [Key in ExposureName]: ExposureValue }
          : {}
    : {};

type AllowedAppStartYield =
  | ServiceYieldRequest<any, any, any, any, any>
  | ServiceDependencyAccessRequest<string, unknown>;

type ServiceAppStartRequest<Yielded = never> = Readonly<{
  [SERVICE_APP_START_REQUEST_MARKER]: true;
  readonly [SERVICE_APP_START_CALLBACK_YIELDED]?: Yielded;
  run: () => AppStartResult | Generator<Yielded, AppStartResult, unknown>;
}>;

type AbstractMarker<Contract> = {
  readonly [ABSTRACT_SERVICE_MARKER]: () => Contract;
};

type RequirementContract<Requirement> =
  Requirement extends ServiceRequirement<infer Contract, any>
    ? Contract
    : never;

export type ServiceRequirement<Contract, Name extends string = string> = {
  readonly [SERVICE_REQUIREMENT_MARKER]: true;
  readonly name: Name;
  readonly [SERVICE_REQUIREMENT_TOKEN]: object;
};

type ServiceRuntimeMetaDefinition<
  Name extends string,
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
  AppStart extends boolean = false,
  ProvidedInput = ServiceProvidedInput<Inputs>,
  ProvideArgs extends unknown[] = ProvideArguments<ProvidedInput>,
> = ServiceMetaData<
  Name,
  Scope,
  ServiceCallInputs<Scope, Inputs>,
  Output,
  ResolveServiceTrackingMetadata<Metadata>,
  (...args: any[]) => unknown,
  Metadata,
  ProvidedInput,
  ProvideArgs,
  TrackingBrowserBoundary<Metadata>,
  AppStart
>;

type InjectHelper<
  Name extends string,
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
  AppStart extends boolean = false,
  ProvidedInput = ServiceProvidedInput<Inputs>,
  ProvideArgs extends unknown[] = ProvideArguments<ProvidedInput>,
> = {
  [Key in `inject${Capitalize<Name>}`]: WithTrackedDependencies<
    WithServiceRuntimeMeta<
      {
        (): MaybeErrorOutput<
          ServiceCallInputs<Scope, Inputs>,
          undefined,
          Output
        >;
        <Config extends Partial<PublicInputBindings<Inputs, Scope>>>(
          bindings: StrictBindings<
            Partial<PublicInputBindings<Inputs, Scope>>,
            Config
          >,
        ): MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>;
        <
          Exposed extends object,
          Yielded extends ExposureYield<
            SelectableOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >
          > = never,
        >(
          bindings: undefined,
          expose: ExposureSelector<
            SelectableOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >,
            Exposed,
            Yielded
          >,
        ): ExposedOutput<
          SelectableOutput<ServiceCallInputs<Scope, Inputs>, undefined, Output>,
          MaterializeExposureResult<ValidateRootExposure<Exposed>>
        >;
        <
          Config extends Partial<PublicInputBindings<Inputs, Scope>>,
          Exposed extends object,
          Yielded extends ExposureYield<
            SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>
          > = never,
        >(
          bindings: StrictBindings<
            Partial<PublicInputBindings<Inputs, Scope>>,
            Config
          >,
          expose: ExposureSelector<
            SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
            Exposed,
            Yielded
          >,
        ): ExposedOutput<
          SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
          MaterializeExposureResult<ValidateRootExposure<Exposed>>
        >;
      } & InjectPropertyShortcuts<Scope, Inputs, Output, Metadata> &
        (keyof ServiceCallInputs<Scope, Inputs> extends never
          ? {}
          : {
              OmitInputs: OmitInputsInjectShortcuts<
                Scope,
                Inputs,
                Output,
                Metadata
              >;
            }),
      ServiceRuntimeMetaDefinition<
        Name,
        Scope,
        Inputs,
        Output,
        Metadata,
        AppStart,
        ProvidedInput,
        ProvideArgs
      >
    >,
    Metadata
  >;
};

type SinglePropertyDerivedProperties<
  Output extends object,
  Key extends OutputDependencyKeys<Output>,
> = DerivedPropertiesTracking<
  {
    [Property in Key]: Output[Property];
  },
  {
    [Property in Key]: Output[Property];
  }
>;

type WithSinglePropertyDerivedProperties<
  Metadata extends AnyServiceTrackingMetadata,
  Output extends object,
  Key extends OutputDependencyKeys<Output>,
> =
  Metadata extends ServiceTrackingMetadata<
    infer Name extends string,
    infer Scope extends ConcreteServiceScope,
    infer ServiceOutput,
    infer ChildYielded,
    any,
    infer ProvidedInput,
    infer BrowserBoundary extends boolean,
    infer AppStart extends boolean
  >
    ? ServiceTrackingMetadata<
        Name,
        Scope,
        ServiceOutput,
        ChildYielded,
        SinglePropertyDerivedProperties<Output, Key>,
        ProvidedInput,
        BrowserBoundary,
        AppStart
      >
    : never;

type NestedPropertyValue<V, NestedKey> = V extends object
  ? NestedKey extends keyof V
    ? V[NestedKey]
    : never
  : never;

type NestedPropertyDerivedProperties<
  Output extends object,
  Key extends OutputDependencyKeys<Output>,
  NestedKey extends keyof (Output[Key] extends object ? Output[Key] : never),
> = DerivedPropertiesTracking<
  {
    [K in Key]: Output[K] extends infer V
      ? V extends object
        ? { [NK in NestedKey & keyof V]: V[NK] }
        : never
      : never;
  },
  {
    [K in Key]: Output[K] extends infer V
      ? V extends object
        ? { [NK in NestedKey & keyof V]: V[NK] }
        : never
      : never;
  }
>;

type WithNestedPropertyDerivedProperties<
  Metadata extends AnyServiceTrackingMetadata,
  Output extends object,
  Key extends OutputDependencyKeys<Output>,
  NestedKey extends keyof (Output[Key] extends object ? Output[Key] : never),
> =
  Metadata extends ServiceTrackingMetadata<
    infer Name extends string,
    infer Scope extends ConcreteServiceScope,
    infer ServiceOutput,
    infer ChildYielded,
    any,
    infer ProvidedInput,
    infer BrowserBoundary extends boolean,
    infer AppStart extends boolean
  >
    ? ServiceTrackingMetadata<
        Name,
        Scope,
        ServiceOutput,
        ChildYielded,
        NestedPropertyDerivedProperties<Output, Key, NestedKey>,
        ProvidedInput,
        BrowserBoundary,
        AppStart
      >
    : never;

type SinglePropertyShortcutResult<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Config,
  Output extends object,
  Key extends OutputDependencyKeys<Output>,
> =
  MaybeErrorOutput<
    ServiceCallInputs<Scope, Inputs>,
    Config,
    Output
  > extends infer Result
    ? Result extends object
      ? Key extends keyof Result
        ? Result[Key]
        : never
      : Result
    : never;

/**
 * What driving a yield shortcut returns for a member: a reactive reader is
 * read, so `yield* View.todos.status()` is the status itself; any other member
 * (object, method, or a resource such as a by-identifier mutation, which is a
 * reader but is consumed as the resource) is returned as is.
 */
type ShortcutRead<Member> = [Member] extends [{ readonly type: string }]
  ? Member
  : [Member] extends [
        {
          readonly [YIELDABLE_VALUE]: string;
          readonly [REACTIVE_VALUE_TYPE]: infer Value;
        },
      ]
    ? Value
    : Member;

type SinglePropertyShortcutGenerator<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Config,
  Key extends OutputDependencyKeys<Output>,
> = Generator<
  ServiceYieldRequest<
    Scope,
    MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
    WithSinglePropertyDerivedProperties<Metadata, Output, Key>,
    Key & string,
    SinglePropertyShortcutResult<Scope, Inputs, Config, Output, Key>
  >,
  ShortcutRead<
    SinglePropertyShortcutResult<Scope, Inputs, Config, Output, Key>
  >,
  unknown
>;

type InjectPropertyShortcut<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
> = WithTrackedDependencies<
  (keyof ServiceCallInputs<Scope, Inputs> extends never
    ? {
        (): SinglePropertyShortcutResult<Scope, Inputs, undefined, Output, Key>;
      }
    : {}) & {
    <Config extends Partial<PublicInputBindings<Inputs, Scope>>>(
      bindings: StrictBindings<
        Partial<PublicInputBindings<Inputs, Scope>>,
        Config
      >,
    ): SinglePropertyShortcutResult<Scope, Inputs, Config, Output, Key>;
  } & (keyof ServiceCallInputs<Scope, Inputs> extends never
      ? Output[Key] extends (...args: infer Args) => infer Result
        ? Args extends []
          ? {}
          : (...args: Args) => ResolveGeneratorResult<Result>
        : {}
      : {}) &
    NestedInjectPropertyShortcuts<Scope, Inputs, Output, Metadata, Key>,
  WithSinglePropertyDerivedProperties<Metadata, Output, Key>
>;

type NestedInjectPropertyShortcut<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
  NestedKey extends keyof (Output[Key] extends object ? Output[Key] : never),
> = WithTrackedDependencies<
  {
    (): WithTrackedDependencies<
      NestedPropertyValue<Output[Key], NestedKey>,
      WithNestedPropertyDerivedProperties<Metadata, Output, Key, NestedKey>
    >;
    <Config extends Partial<PublicInputBindings<Inputs, Scope>>>(
      bindings: StrictBindings<
        Partial<PublicInputBindings<Inputs, Scope>>,
        Config
      >,
    ): WithTrackedDependencies<
      NestedPropertyValue<Output[Key], NestedKey>,
      WithNestedPropertyDerivedProperties<Metadata, Output, Key, NestedKey>
    >;
  } & DeepInjectPropertyShortcuts<
    Scope,
    Inputs,
    Output,
    Metadata,
    Key,
    NestedKey,
    NestedPropertyValue<Output[Key], NestedKey>,
    ShortcutDepthBudget
  >,
  WithNestedPropertyDerivedProperties<Metadata, Output, Key, NestedKey>
>;

/** Inject-context counterpart of {@link DeepYieldPropertyShortcuts}. */
type DeepInjectPropertyShortcuts<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
  NestedKey extends keyof (Output[Key] extends object ? Output[Key] : never),
  Value,
  Budget extends readonly unknown[],
> = Budget extends readonly []
  ? {}
  : Value extends readonly unknown[]
    ? {}
    : Value extends object
      ? {
          [Member in Exclude<
            Extract<keyof Value, string>,
            Exclude<keyof Function, 'call'> | 'then'
          >]: WithTrackedDependencies<
            {
              (): Value[Member];
              <Config extends Partial<PublicInputBindings<Inputs, Scope>>>(
                bindings: StrictBindings<
                  Partial<PublicInputBindings<Inputs, Scope>>,
                  Config
                >,
              ): Value[Member];
            } & (keyof ServiceCallInputs<Scope, Inputs> extends never
              ? Value[Member] extends (...args: infer Args) => infer Result
                ? Args extends []
                  ? {}
                  : (...args: Args) => ResolveGeneratorResult<Result>
                : {}
              : {}) &
              DeepInjectPropertyShortcuts<
                Scope,
                Inputs,
                Output,
                Metadata,
                Key,
                NestedKey,
                Value[Member],
                Budget extends readonly [unknown, ...infer Rest]
                  ? Rest
                  : readonly []
              >,
            WithNestedPropertyDerivedProperties<
              Metadata,
              Output,
              Key,
              NestedKey
            >
          >;
        }
      : {};

type NestedInjectPropertyShortcuts<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
> = Output[Key] extends object
  ? {
      [NestedKey in Exclude<
        keyof Output[Key],
        Exclude<keyof Function, 'call'> | 'then'
      >]: NestedInjectPropertyShortcut<
        Scope,
        Inputs,
        Output,
        Metadata,
        Key,
        NestedKey
      >;
    }
  : {};

type YieldPropertyShortcut<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
> = WithTrackedDependencies<
  (keyof ServiceCallInputs<Scope, Inputs> extends never
    ? IsMethodShortcutMember<Output[Key]> extends true
      ? {}
      : {
          (): SinglePropertyShortcutGenerator<
            Scope,
            Inputs,
            Output,
            Metadata,
            undefined,
            Key
          >;
        }
    : {}) & {
    <Config extends Partial<PublicInputBindings<Inputs, Scope>>>(
      bindings: StrictBindings<
        Partial<PublicInputBindings<Inputs, Scope>>,
        Config
      >,
    ): IsMethodShortcutMember<Output[Key]> extends true
      ? // The bindings pick the instance; its method is called, not exposed.
        Generator<
          ServiceYieldRequest<
            Scope,
            MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
            WithSinglePropertyDerivedProperties<Metadata, Output, Key>
          >,
          Output[Key] extends (...args: any[]) => infer Result
            ? ResolveGeneratorResult<Result>
            : never,
          unknown
        >
      : SinglePropertyShortcutGenerator<
          Scope,
          Inputs,
          Output,
          Metadata,
          Config,
          Key
        >;
  } & (keyof ServiceCallInputs<Scope, Inputs> extends never
      ? Output[Key] extends (...args: infer Args) => infer Result
        ? Args extends []
          ? IsMethodShortcutMember<Output[Key]> extends true
            ? // A method is called, even without arguments, and not exposed.
              () => Generator<
                ServiceYieldRequest<
                  Scope,
                  MaybeErrorOutput<
                    ServiceCallInputs<Scope, Inputs>,
                    undefined,
                    Output
                  >,
                  WithSinglePropertyDerivedProperties<Metadata, Output, Key>
                >,
                ResolveGeneratorResult<Result>,
                unknown
              >
            : {}
          : (
              ...args: Args
            ) => Generator<
              ServiceYieldRequest<
                Scope,
                MaybeErrorOutput<
                  ServiceCallInputs<Scope, Inputs>,
                  undefined,
                  Output
                >,
                WithSinglePropertyDerivedProperties<Metadata, Output, Key>,
                IsMethodShortcutMember<Output[Key]> extends true
                  ? never
                  : Key & string,
                ResolveGeneratorResult<Result>
              >,
              ResolveGeneratorResult<Result>,
              unknown
            >
        : {}
      : {}) &
    ShortcutName<Output[Key], Key & string> &
    ShortcutSettledBrand<Output[Key]> &
    ShortcutMember<
      Scope,
      Inputs,
      Output,
      WithSinglePropertyDerivedProperties<Metadata, Output, Key>,
      Output[Key]
    > &
    NestedYieldPropertyShortcuts<Scope, Inputs, Output, Metadata, Key>,
  WithSinglePropertyDerivedProperties<Metadata, Output, Key>
>;

/**
 * The member a shortcut designates, neither read nor called: what
 * `craftExpose('save', View.save)` exposes.
 */
type ShortcutMember<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Member,
> = ShortcutMemberCarrier<
  ServiceYieldRequest<
    Scope,
    MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, undefined, Output>,
    Metadata
  >,
  Member
>;

type NestedYieldPropertyShortcut<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
  NestedKey extends keyof (Output[Key] extends object ? Output[Key] : never),
> = WithTrackedDependencies<
  (IsMethodShortcutMember<
    NestedPropertyValue<Output[Key], NestedKey>
  > extends true
    ? {}
    : {
        (): Generator<
          ServiceYieldRequest<
            Scope,
            NestedPropertyValue<Output[Key], NestedKey>,
            WithNestedPropertyDerivedProperties<
              Metadata,
              Output,
              Key,
              NestedKey
            >,
            NestedKey & string,
            NestedPropertyValue<Output[Key], NestedKey>
          >,
          ShortcutRead<NestedPropertyValue<Output[Key], NestedKey>>,
          unknown
        >;
      }) & {
    <Config extends Partial<PublicInputBindings<Inputs, Scope>>>(
      bindings: StrictBindings<
        Partial<PublicInputBindings<Inputs, Scope>>,
        Config
      >,
    ): Generator<
      ServiceYieldRequest<
        Scope,
        NestedPropertyValue<Output[Key], NestedKey>,
        WithNestedPropertyDerivedProperties<Metadata, Output, Key, NestedKey>,
        IsMethodShortcutMember<
          NestedPropertyValue<Output[Key], NestedKey>
        > extends true
          ? never
          : NestedKey & string,
        NestedPropertyValue<Output[Key], NestedKey>
      >,
      ShortcutRead<NestedPropertyValue<Output[Key], NestedKey>>,
      unknown
    >;
  } & (keyof ServiceCallInputs<Scope, Inputs> extends never
      ? NestedPropertyValue<Output[Key], NestedKey> extends (
          ...args: infer Args
        ) => infer Result
        ? (
            ...args: Args
          ) => Generator<
            ServiceYieldRequest<
              Scope,
              MaybeErrorOutput<
                ServiceCallInputs<Scope, Inputs>,
                undefined,
                Output
              >,
              WithNestedPropertyDerivedProperties<
                Metadata,
                Output,
                Key,
                NestedKey
              >,
              never,
              ResolveGeneratorResult<Result>
            >,
            ResolveGeneratorResult<Result>,
            unknown
          > &
            ShortcutSettledBrand<ResolveGeneratorResult<Result>> &
            DeepYieldPropertyShortcuts<
              Scope,
              Inputs,
              Output,
              Metadata,
              Key,
              NestedKey,
              ResolveGeneratorResult<Result>,
              ShortcutDepthBudget
            >
        : {}
      : {}) &
    ShortcutName<
      NestedPropertyValue<Output[Key], NestedKey>,
      NestedKey & string
    > &
    ShortcutSettledBrand<NestedPropertyValue<Output[Key], NestedKey>> &
    ShortcutMember<
      Scope,
      Inputs,
      Output,
      WithNestedPropertyDerivedProperties<Metadata, Output, Key, NestedKey>,
      NestedPropertyValue<Output[Key], NestedKey>
    > &
    DeepYieldPropertyShortcuts<
      Scope,
      Inputs,
      Output,
      Metadata,
      Key,
      NestedKey,
      NestedPropertyValue<Output[Key], NestedKey>,
      ShortcutDepthBudget
    >,
  WithNestedPropertyDerivedProperties<Metadata, Output, Key, NestedKey>
>;

/**
 * A member a yield shortcut calls instead of returning: a `craftMethod`, or a
 * function that is not a reactive reader. `View.form.submit()` runs `submit`.
 */
type IsMethodShortcutMember<Value> = 0 extends 1 & Value
  ? // `any` stays a readable member, as it was before methods were told apart.
    false
  : [Value] extends [{ readonly [CRAFT_METHOD]: true }]
    ? true
    : [Value] extends [{ readonly [YIELDABLE_VALUE]: string }]
      ? false
      : [Value] extends [Signal<any>]
        ? false
        : [Value] extends [(...args: any[]) => any]
          ? true
          : false;

/**
 * A shortcut onto a reactive reader is named after its member, so that it can
 * stand wherever a named reactive value is required (`ifNode(View.isOpen, …)`).
 */
/**
 * What a settled read advertises (the async source it waits on, the exceptions
 * it may raise): kept on the shortcut so `pendingNode` / `catchNode` still see
 * it when a template binds the member through its shortcut.
 */
type ShortcutSettledBrand<Value> = ([CraftSettledSourcesOf<Value>] extends [
  never,
]
  ? {}
  : CraftSettledBrand<
      CraftSettledSourcesOf<Value>,
      CraftSettledExceptionsOf<Value>
    >) &
  // A form field reached through a shortcut keeps the validation metadata its
  // insertions gave it, which `fieldErrorNode` checks its cases against. The
  // carriers are optional, hence the key guard: without it every value matches.
  (typeof CRAFT_FIELD_VALIDATION_CASES extends keyof Value
    ? Pick<Value, typeof CRAFT_FIELD_VALIDATION_CASES>
    : {}) &
  (typeof CRAFT_FIELD_VALIDATORS extends keyof Value
    ? Pick<Value, typeof CRAFT_FIELD_VALIDATORS>
    : {});

type ShortcutName<Value, Name extends string> = [Value] extends [
  { readonly [YIELDABLE_VALUE]: string },
]
  ? { readonly [YIELDABLE_VALUE]: Name }
  : {};

/** How many levels below `service.key.nested` a shortcut chain keeps typing. */
type ShortcutDepthBudget = readonly [
  unknown,
  unknown,
  unknown,
  unknown,
  unknown,
  unknown,
];

/**
 * The members of a value reached through a shortcut. Data leaves (arrays,
 * primitives) have none; a function keeps the members attached to it, which is
 * how a reactive reader carries its own methods.
 */
type DeepYieldPropertyShortcuts<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
  NestedKey extends keyof (Output[Key] extends object ? Output[Key] : never),
  Value,
  Budget extends readonly unknown[],
> = Budget extends readonly []
  ? {}
  : Value extends readonly unknown[]
    ? {}
    : Value extends object
      ? {
          [Member in Exclude<
            Extract<keyof Value, string>,
            Exclude<keyof Function, 'call'> | 'then'
          >]: DeepYieldPropertyShortcut<
            Scope,
            Inputs,
            Output,
            Metadata,
            Key,
            NestedKey,
            Value[Member],
            Member,
            Budget extends readonly [unknown, ...infer Rest]
              ? Rest
              : readonly []
          >;
        }
      : {};

/**
 * One node of a shortcut chain below `service.key.nested`: reads the member it
 * designates, calls it when it is a method, and exposes its own members.
 */
type DeepYieldPropertyShortcut<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
  NestedKey extends keyof (Output[Key] extends object ? Output[Key] : never),
  Value,
  Name extends string,
  Budget extends readonly unknown[],
> = WithTrackedDependencies<
  (IsMethodShortcutMember<Value> extends true
    ? {}
    : {
        (): Generator<
          ServiceYieldRequest<
            Scope,
            Value,
            WithNestedPropertyDerivedProperties<
              Metadata,
              Output,
              Key,
              NestedKey
            >,
            Name,
            Value
          >,
          ShortcutRead<Value>,
          unknown
        >;
      }) & {
    <Config extends Partial<PublicInputBindings<Inputs, Scope>>>(
      bindings: StrictBindings<
        Partial<PublicInputBindings<Inputs, Scope>>,
        Config
      >,
    ): Generator<
      ServiceYieldRequest<
        Scope,
        Value,
        WithNestedPropertyDerivedProperties<Metadata, Output, Key, NestedKey>,
        IsMethodShortcutMember<Value> extends true ? never : Name,
        Value
      >,
      ShortcutRead<Value>,
      unknown
    >;
  } & (keyof ServiceCallInputs<Scope, Inputs> extends never
      ? Value extends (...args: infer Args) => infer Result
        ? (
            ...args: Args
          ) => Generator<
            ServiceYieldRequest<
              Scope,
              MaybeErrorOutput<
                ServiceCallInputs<Scope, Inputs>,
                undefined,
                Output
              >,
              WithNestedPropertyDerivedProperties<
                Metadata,
                Output,
                Key,
                NestedKey
              >
            >,
            ResolveGeneratorResult<Result>,
            unknown
          > &
            ShortcutSettledBrand<ResolveGeneratorResult<Result>> &
            DeepYieldPropertyShortcuts<
              Scope,
              Inputs,
              Output,
              Metadata,
              Key,
              NestedKey,
              ResolveGeneratorResult<Result>,
              Budget
            >
        : {}
      : {}) &
    ShortcutName<Value, Name> &
    ShortcutSettledBrand<Value> &
    ShortcutMember<
      Scope,
      Inputs,
      Output,
      WithNestedPropertyDerivedProperties<Metadata, Output, Key, NestedKey>,
      Value
    > &
    DeepYieldPropertyShortcuts<
      Scope,
      Inputs,
      Output,
      Metadata,
      Key,
      NestedKey,
      Value,
      Budget
    >,
  WithNestedPropertyDerivedProperties<Metadata, Output, Key, NestedKey>
>;

type NestedYieldPropertyShortcuts<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
> = Output[Key] extends object
  ? {
      [NestedKey in Exclude<
        keyof Output[Key],
        Exclude<keyof Function, 'call'> | 'then'
      >]: NestedYieldPropertyShortcut<
        Scope,
        Inputs,
        Output,
        Metadata,
        Key,
        NestedKey
      >;
    }
  : {};

type YieldPropertyShortcuts<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
> = Output extends object
  ? {
      [Key in Exclude<
        OutputDependencyKeys<Output>,
        Exclude<keyof Function, 'call'> | 'then'
      >]: YieldPropertyShortcut<Scope, Inputs, Output, Metadata, Key>;
    }
  : {};

type InjectPropertyShortcuts<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
> = Output extends object
  ? {
      [Key in Exclude<
        OutputDependencyKeys<Output>,
        Exclude<keyof Function, 'call'> | 'then'
