  : {};

type OmitInputsInjectPropertyShortcut<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
> = WithTrackedDependencies<
  {
    (): SinglePropertyShortcutResult<Scope, Inputs, undefined, Output, Key>;
  } & NestedInjectPropertyShortcuts<Scope, Inputs, Output, Metadata, Key>,
  WithSinglePropertyDerivedProperties<Metadata, Output, Key>
>;

type OmitInputsInjectShortcuts<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
> = Output extends object
  ? {
      [Key in Exclude<
        OutputDependencyKeys<Output>,
        Exclude<keyof Function, 'call'> | 'then'
      >]: OmitInputsInjectPropertyShortcut<
        Scope,
        Inputs,
        Output,
        Metadata,
        Key
      >;
    }
  : {};

type OmitInputsYieldPropertyShortcut<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output extends object,
  Metadata extends AnyServiceTrackingMetadata,
  Key extends OutputDependencyKeys<Output>,
> = WithTrackedDependencies<
  {
    (): SinglePropertyShortcutGenerator<
      Scope,
      Inputs,
      Output,
      Metadata,
      undefined,
      Key
    >;
  } & NestedYieldPropertyShortcuts<Scope, Inputs, Output, Metadata, Key>,
  WithSinglePropertyDerivedProperties<Metadata, Output, Key>
>;

type OmitInputsYieldShortcuts<
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
> = Output extends object
  ? {
      [Key in Exclude<
        OutputDependencyKeys<Output>,
        Exclude<keyof Function, 'call'> | 'then'
      >]: OmitInputsYieldPropertyShortcut<Scope, Inputs, Output, Metadata, Key>;
    }
  : {};

type YieldHelper<
  Name extends string,
  Scope extends ConcreteServiceScope,
  Inputs extends object,
  Output,
  Metadata extends AnyServiceTrackingMetadata,
  AppStart extends boolean = false,
  ProvidedInput = ServiceProvidedInput<Inputs>,
  ProvideArgs extends unknown[] = ProvideArguments<ProvidedInput>,
> = {
  [Key in Capitalize<Name>]: WithTrackedDependencies<
    WithServiceRuntimeMeta<
      {
        (): Generator<
          ServiceYieldRequest<
            Scope,
            MaybeErrorOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >,
            Metadata,
            Uncapitalize<Name>,
            MaybeErrorOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >
          >,
          MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, undefined, Output>,
          unknown
        >;
        <Config extends Partial<PublicInputBindings<Inputs, Scope>>>(
          bindings: StrictBindings<
            Partial<PublicInputBindings<Inputs, Scope>>,
            Config
          >,
        ): Generator<
          ServiceYieldRequest<
            Scope,
            MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
            Metadata,
            Uncapitalize<Name>,
            MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>
          >,
          MaybeErrorOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
          unknown
        >;
        <
          Exposed extends object,
          Yielded extends ExposureYield<
            SelectableOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >
          > = never,
        >(
          bindings: undefined,
          expose: ExposureSelector<
            SelectableOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >,
            Exposed,
            Yielded
          >,
        ): Generator<
          | ServiceYieldRequest<
              Scope,
              SelectableOutput<
                ServiceCallInputs<Scope, Inputs>,
                undefined,
                Output
              >,
              WithDerivedProperties<Metadata, Exposed, Yielded>
            >
          | ExposureYield<
              SelectableOutput<
                ServiceCallInputs<Scope, Inputs>,
                undefined,
                Output
              >
            >,
          ExposedOutput<
            SelectableOutput<
              ServiceCallInputs<Scope, Inputs>,
              undefined,
              Output
            >,
            MaterializeExposureResult<ValidateRootExposure<Exposed>>
          >,
          unknown
        >;
        <
          Config extends Partial<PublicInputBindings<Inputs, Scope>>,
          Exposed extends object,
          Yielded extends ExposureYield<
            SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>
          > = never,
        >(
          bindings: StrictBindings<
            Partial<PublicInputBindings<Inputs, Scope>>,
            Config
          >,
          expose: ExposureSelector<
            SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
            Exposed,
            Yielded
          >,
        ): Generator<
          | ServiceYieldRequest<
              Scope,
              SelectableOutput<
                ServiceCallInputs<Scope, Inputs>,
                Config,
                Output
              >,
              WithDerivedProperties<Metadata, Exposed, Yielded>
            >
          | ExposureYield<
              SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>
            >,
          ExposedOutput<
            SelectableOutput<ServiceCallInputs<Scope, Inputs>, Config, Output>,
            MaterializeExposureResult<ValidateRootExposure<Exposed>>
          >,
          unknown
        >;
      } & YieldPropertyShortcuts<Scope, Inputs, Output, Metadata> &
        (keyof ServiceCallInputs<Scope, Inputs> extends never
          ? {}
          : {
              OmitInputs: OmitInputsYieldShortcuts<
                Scope,
                Inputs,
                Output,
                Metadata
              >;
            }),
      ServiceRuntimeMetaDefinition<
        Name,
        Scope,
        Inputs,
        Output,
        Metadata,
        AppStart,
        ProvidedInput,
        ProvideArgs
      >
    >,
    Metadata
  >;
};

type ExtractServiceTrackingYielded<Metadata> =
  Metadata extends ServiceTrackingMetadata<
    any,
    any,
    any,
    infer Yielded,
    any,
    any,
    any,
    any
  >
    ? Yielded
    : never;

type ProvideHelper<
  Name extends string,
  Scope extends RealCapableScope,
  Output,
  ProvideArgs extends unknown[],
  Yielded = never,
> = {
  [Key in `provide${Capitalize<Name>}`]: (
    ...args: ProvideArgs
  ) => NamedBrandedServiceProvider<Name, Scope, Output, Yielded>;
