export type ServiceRuntimeOverride =
  | { readonly kind: 'notReached' }
  | {
      readonly kind: 'useValue';
      readonly value: unknown;
    }
  | {
      readonly kind: 'instantiate';
      instance?: unknown;
    };

export const SERVICE_RUNTIME_OVERRIDES = new InjectionToken<
  ReadonlyMap<string, ServiceRuntimeOverride>
>('service-runtime-overrides', {
  factory: () => new Map(),
});

/**
 * A value supplied to a craft service factory.
 *
 * Service inputs are consumed as readers so a service can preserve the
 * reactive-read edge of the value it was given:
 *
 * ```ts
 * function* (inputs: { userId: CraftServiceInput<string> }) {
 *   const userId = yield* inputs.userId();
 *   // ...
 * }
 * ```
 *
 * The public service helper accepts a resolved value, a Craft signal, or
 * another Craft reader for this input.
 */
// The reader yields a reactive read request. It must not default to
// `unknown`: that yield would absorb the service's whole `Yielded` union, and
// with it the named primitives the service exposes.
export type CraftServiceInput<
  Value,
  Yielded = ReactiveReadRequest<Value>,
> = Yieldable<[], Value, Yielded>;

export type MaybeSignal<T> =
  | T
  | Signal<T>
  | YieldableReactiveValue<T>
  | CraftServiceInput<T>;

const SERVICE_INPUT_SOURCE = Symbol('craft-service-input-source');

type ServiceInputReader = CraftServiceInput<unknown> & {
  readonly [SERVICE_INPUT_SOURCE]?: unknown;
};

export function toValue<T>(value: MaybeSignal<T>): T {
  if (isServiceInputReader(value)) {
    return resolveServiceInputSource(value[SERVICE_INPUT_SOURCE]) as T;
  }
  if (isYieldableReactiveValue(value)) {
    return rawReactiveValue(value)() as T;
  }
  if (isSignal(value)) return value() as T;
  return value as T;
}

function isServiceInputReader(value: unknown): value is ServiceInputReader {
  return typeof value === 'function' && SERVICE_INPUT_SOURCE in value;
}

function resolveServiceInputSource(value: unknown): unknown {
  if (isYieldableReactiveValue(value)) {
    return rawReactiveValue(value)();
  }
  if (isSignal(value)) {
    return value();
  }
  if (typeof value === 'function') {
    return value();
  }
  return value;
}

export function onAppStart(
  run: () => AppStartResult,
): Generator<ServiceAppStartRequest<never>, void, unknown>;
export function onAppStart<Yielded extends AllowedAppStartYield>(
  run: () => Generator<Yielded, AppStartResult, unknown>,
): Generator<ServiceAppStartRequest<Yielded>, void, unknown>;
export function onAppStart(
  run: () => Generator<unknown, AppStartResult, unknown>,
): Generator<ServiceAppStartRequest<unknown>, void, unknown>;
export function* onAppStart<Yielded>(
  run: () => AppStartResult | Generator<Yielded, AppStartResult, unknown>,
): Generator<ServiceAppStartRequest<Yielded>, void, unknown> {
  yield createAppStartRequest(run);
}

export function abstract<Contract>(): AbstractMarker<Contract> {
  return {
    [ABSTRACT_SERVICE_MARKER]: () => undefined as Contract,
  } as AbstractMarker<Contract>;
}

/**
 * Creates a named Craft service boundary with generated service,
 * provider, and metadata helpers.
 *
 * `craftService` is designed for composing reactive features through explicit
 * dependencies instead of hidden `inject(...)` calls inside arbitrary code. Each
 * crafted service receives a stable name and scope, which are then reflected in
 * helpers such as:
 *
 * - `Counter(...)`
 * - `provideCounter()` for provider-capable scopes
 * - `provideCounter()` for `manuallyProvidedAtRoot`
 * - `COUNTER_META_DATA`
 *
 * When a service yields other crafted services, its dependency tree becomes
 * available to the type system and to `setupCraftServiceTest(...)`.
 *
 * Partial exposure works through opaque dependency tokens. Returned tokens become
 * public API, while values used internally but not exposed must be declared with
 * `yield* token()`. Callable services can opt back into exposing their root
 * callable through the reserved `$self` token.
 *
 * The supported scopes are:
 *
 * - `global`: root singleton, created when first resolved unless appStart is
 *   enabled
 * - `toProvide`: one instance per injector that registers `provideX()`, created
 *   when first resolved
 * - `manuallyProvidedAtRoot`: explicit provider helper mounted at the root
 * - `function`: new service context on each helper call
 * - `abstract`: typed contract only, with no concrete implementation
 *
 * Practical recommendations for choosing a providedIn:
 *
 * - Use `toProvide` for mutable state or context owned by a component, feature,
 *   or route, even when only one component currently consumes it. Configure
 *   component-owned services with `withComponentProviders` when their values
 *   come from component inputs; consumers then resolve `X()` without repeating
 *   those values. The service is created when its provider token is first
 *   resolved, not when `provideX()` is called.
 * - Use `function` for reusable per-call logic composed by other services. Each
 *   helper call creates a fresh service context and accepts its own call-site
 *   inputs only. It is not a cached store for state owned by one component.
 * - Use `global` when the instance is intentionally shared application-wide.
 * - For startup-only logic that should run when the app boots but is not
 *   injected elsewhere, a `function` service can run together with
 *   `provideAppInitializer(...)`. If the same instance also needs to be
 *   injected by other services, use `global` instead.
 *
 * Factory inputs follow the scope: `global` accepts none; `toProvide` and
 * `manuallyProvidedAtRoot` accept only `$provided`; `function` accepts only
 * call-site inputs; `abstract` has no factory inputs.
 *
 * @example
 * Create a global callable counter service
 * ```ts
 * import { craftService, state } from '@craft-ts/core';
 *
 * const { Counter } = craftService(
 *   { name: 'Counter', providedIn: 'global' },
 *   () =>
 *     state(0, ({ update }) => ({
 *       increment: () => update((value) => value + 1),
 *     })),
 * );
 * ```
 *
 * @example
 * Compose another service through `yield*`
 * ```ts
 * const { Counter } = craftService(
 *   { name: 'Counter', providedIn: 'global' },
 *   () =>
 *     state(0, ({ update }) => ({
 *       increment: () => update((value) => value + 1),
 *     })),
 * );
 *
 * const { CounterFacade } = craftService(
 *   { name: 'CounterFacade', providedIn: 'global' },
 *   function* () {
 *     const counter = yield* Counter();
 *
 *     return {
 *       read: () => counter(),
 *       increment: () => counter.increment(),
 *     };
 *   },
 * );
 * ```
 *
 * @example
 * Expose only part of a dependency through opaque tokens
 * ```ts
 * const { Counter } = craftService(
 *   { name: 'Counter', providedIn: 'toProvide' },
 *   () =>
 *     state(0, ({ update }) => ({
 *       increment: () => update((value) => value + 1),
 *       decrement: () => update((value) => value - 1),
 *     })),
 * );
 *
 * const { CounterExtended } = craftService(
 *   { name: 'CounterExtended', providedIn: 'toProvide' },
 *   function* () {
 *     return yield* Counter(undefined, ({ $self, increment }) => ({
 *       $self,
 *       incrementCounter: increment,
 *     }));
 *   },
 * );
 * ```
 *
 * @example
 * Build a global utility around a browser boundary dependency
 * ```ts
 * import { LocalStorageService, craftService } from '@craft-ts/core';
 *
 * const { GlobalPersisterHandlerService } = craftService(
 *   { name: 'GlobalPersisterHandlerService', providedIn: 'global' },
 *   function* () {
 *     const storage = yield* LocalStorageService(
 *       undefined,
 *       ({ key, length, removeItem }) => ({
 *         key,
 *         length,
 *         removeItem,
 *       }),
 *     );
 *
 *     return {
 *       clearAllCache: () => {
 *         const keysToRemove: string[] = [];
 *
 *         for (let index = 0; index < storage.length(); index++) {
 *           const keyName = storage.key(index);
 *           if (keyName?.startsWith('craft-ts-')) {
 *             keysToRemove.push(keyName);
 *           }
 *         }
 *
 *         keysToRemove.forEach((keyName) => storage.removeItem(keyName));
 *       },
 *     };
 *   },
 * );
 * ```
 */
export function craftService<Name extends string, Contract>(
  options: { name: Name; providedIn: 'abstract' },
  marker: AbstractMarker<Contract>,
): AbstractServiceApi<Name, Contract>;
export function craftService<
  Name extends string,
