/**
 * @internal A craft service whose factory's RESULT is the service — a DI slot
 * (`(inputs: { $provided: X }) => inputs.$provided ?? fallback`), a collection
 * contribution, an adapted external value. Same scopes, providers and tracking
 * as {@link craftService}; only the public `craftService` requires a generator
 * whose named primitives are exposed.
 */
export function ɵcraftValueService<
  Name extends string,
  Scope extends ConcreteServiceScope,
  Factory extends AnyFactory,
  BrowserBoundary extends boolean = false,
>(
  options: {
    name: Name;
    providedIn: Scope;
    browserBoundary?: BrowserBoundary;
    providers?: readonly Provider[];
    collection?: boolean;
  },
  factory: Factory &
    ValidateCraftServiceInputScope<Scope, FactoryInputs<Factory>> &
    ValidateFactoryScope<Scope, Factory>,
): ConcreteServiceApi<
  Name,
  Scope,
  FactoryInputs<Factory>,
  ValueFactoryOutput<Factory>,
  ServiceHelperMetadata<
    Name,
    Scope,
    Factory,
    BrowserBoundary,
    false,
    ValueFactoryOutput<Factory>
  >,
  false
>;
export function ɵcraftValueService(
  options: CraftServiceRuntimeOptions,
  factory: AnyFactory,
): unknown {
  return createCraftServiceApi(options, factory, 'value');
}

function createCraftServiceApi(
  options: CraftServiceRuntimeOptions,
  factoryOrMarker: AnyFactory | AbstractMarker<unknown>,
  exposure: ServiceExposure,
): unknown {
  const capitalizedName = capitalize(options.name);
  const provideName = `provide${capitalizedName}`;
  const serviceName = capitalizedName;
  const requirementName = `${capitalizedName}Requirement`;
  const metaDataName = toMetaDataPropertyName(options.name);

  if (options.providedIn === 'abstract') {
    assertAbstractMarker(factoryOrMarker);
    const token = new InjectionToken<unknown>(
      `${capitalizedName}AbstractServiceToken`,
    );
    const requirement = createServiceRequirement(options.name, token);

    // A minimal definition so `X()` resolves the requirement token (the
    // concrete implementation bound through `provideX`) via the injector. The
    // factory is never invoked: scope is not `function`, so resolution goes
    // straight to `injector.get(token)` (or a registered test override by name).
    const abstractYieldDefinition: ConcreteRuntimeDefinition = {
      factory: () => undefined,
      name: options.name,
      providedIn: 'toProvide',
      browserBoundary: false,
      appStart: false,
      collection: false,
      token,
      requirement,
      hasPublicInput: false,
      hasProvidedInput: false,
      appStartHooks: new Map(),
      startedAppStartServices: new Set(),
      exposure: 'value',
    };

    // The helper closes over metadata that is initialized immediately below.
    // eslint-disable-next-line prefer-const
    let abstractMetaData: InternalServiceMetaData;

    const abstractInjectHelper = () => {
      assertInInjectionContext(abstractInject);
      return inject(token);
    };
    const abstractHelper = createHelper(
      abstractYieldDefinition,
      () => abstractMetaData,
    );

    const abstractApi: Record<string, unknown> = {
      [serviceName]: abstractHelper,
      [requirementName]: requirement,
      [provideName]: (factory: AnyFactory) => {
        const abstractRuntimeDefinition: ConcreteRuntimeDefinition = {
          factory,
          name: options.name,
          providedIn: 'toProvide',
          browserBoundary: false,
          appStart: false,
          collection: false,
          token,
          requirement,
          hasPublicInput: factoryUsesPublicInput(factory),
          hasProvidedInput: factoryUsesProvidedInput(factory),
          appStartHooks: new Map(),
          startedAppStartServices: new Set(),
          exposure: 'value',
        };
        return createProviders(abstractRuntimeDefinition);
      },
    };

    abstractMetaData = createServiceMetaData({
      name: options.name,
      providedIn: 'toProvide',
      inject: abstractInjectHelper,
      runtimeDefinition: abstractYieldDefinition,
    });
    abstractApi[metaDataName] = abstractMetaData;

    attachServiceRuntimeMeta(abstractHelper, abstractMetaData);
    attachServiceRuntimeMeta(abstractInjectHelper, abstractMetaData);
    definitionByReference.set(abstractHelper, abstractYieldDefinition);

    REGISTERED_SERVICES.set(
      options.name,
      abstractInjectHelper as unknown as ServiceReference,
    );

    return abstractApi;
  }

  const concreteFactory = factoryOrMarker as AnyFactory;
  const runtimeDefinition: ConcreteRuntimeDefinition = {
    factory: concreteFactory,
    name: options.name,
    providedIn: options.providedIn,
    browserBoundary: options.browserBoundary ?? false,
    appStart: options.appStart ?? false,
    collection: options.collection ?? false,
    providers: options.providers,
    requirement: options.requirement,
    hasPublicInput: factoryUsesPublicInput(concreteFactory),
    hasProvidedInput: factoryUsesProvidedInput(concreteFactory),
    appStartHooks: new Map(),
    startedAppStartServices: new Set(),
    exposure,
  };

  const token =
    options.providedIn === 'global'
      ? new InjectionToken(`${capitalizedName}ServiceToken`, {
          providedIn: 'root',
          factory: () =>
            createConcreteServiceInstance(runtimeDefinition, inject(Injector)),
        })
      : options.providedIn === 'function'
        ? undefined
        : new InjectionToken(`${capitalizedName}ServiceToken`);
  runtimeDefinition.token = token;

  // The helper closes over metadata that is initialized immediately below.
  // eslint-disable-next-line prefer-const
  let serviceMetaData: InternalServiceMetaData;

  const api: Record<string, unknown> = {
    [serviceName]: createHelper(runtimeDefinition, () => serviceMetaData),
  };

  const injectHelper = createInjectHelper(
    runtimeDefinition,
    () => serviceMetaData,
    concreteInject,
  );

  if (
    options.providedIn === 'toProvide' ||
    options.providedIn === 'manuallyProvidedAtRoot'
  ) {
    api[provideName] = (...provided: unknown[]) =>
      createProviders(runtimeDefinition, provided);
  }

  serviceMetaData = createServiceMetaData({
    name: options.name,
    providedIn: options.providedIn,
    inject: injectHelper,
    provide:
      options.providedIn === 'toProvide' ||
      options.providedIn === 'manuallyProvidedAtRoot'
        ? (api[provideName] as
            | ((...args: any[]) => CraftServiceProvider)
            | undefined)
        : undefined,
    runtimeDefinition,
  });
  api[metaDataName] = serviceMetaData;

  attachServiceRuntimeMeta(injectHelper, serviceMetaData);
  attachServiceRuntimeMeta(api[serviceName], serviceMetaData);
  definitionByReference.set(api[serviceName] as object, runtimeDefinition);

  REGISTERED_SERVICES.set(
    runtimeDefinition.name,
    injectHelper as ServiceReference,
  );

  if (runtimeDefinition.appStart) {
    REGISTERED_APP_START_SERVICES.set(
      runtimeDefinition.name,
      injectHelper as ServiceReference,
    );
  }

  return api;

  function abstractInject() {
    return;
  }
  function concreteInject() {
    return;
  }
}

function createInjectHelper(
  definition: ConcreteRuntimeDefinition,
  getMetaData: () => InternalServiceMetaData | undefined,
  injectMarker: () => void,
) {
  const propertyHelpers = new Map<string, unknown>();
  let omitInputsProxy: object | null = null;

  const injectHelper = (
    bindings?: Record<string, unknown>,
    expose?: RuntimeExposureSelector,
  ) => {
    assertInInjectionContext(injectMarker);
    const injector = inject(Injector);
    const serviceValue = resolveConcreteService(definition, injector, bindings);
    return expose
      ? resolveExposedService(
          serviceValue,
          expose,
          injector,
          definition.providedIn,
        )
      : serviceValue;
  };

  const outerProxy = new Proxy(injectHelper, {
    get(target, property, receiver) {
      if (typeof property !== 'string') {
        return Reflect.get(target, property, receiver);
      }

      if (property === 'then' || property in target) {
        return Reflect.get(target, property, receiver);
      }

      if (property === 'OmitInputs') {
        if (!omitInputsProxy) {
          omitInputsProxy = new Proxy({} as object, {
            get(_, subProp, subReceiver) {
              return wrapOmitInputsHelper(
                Reflect.get(outerProxy, subProp, subReceiver),
              );
            },
          });
        }
        return omitInputsProxy;
      }

      if (!propertyHelpers.has(property)) {
        const nestedPropertyHelpers = new Map<string, unknown>();

        const propertyHelperFn = (...args: unknown[]) => {
          assertInInjectionContext(injectMarker);
          const omitInputs = args[0] === OMIT_INPUTS_BINDINGS;
          const callArgs = omitInputs ? args.slice(1) : args;
          const isDirectCall =
            callArgs.length > 0 && !definition.hasPublicInput;
          const injector = inject(Injector);
          const serviceValue = resolveConcreteService(
            definition,
            injector,
            omitInputs
              ? OMIT_INPUTS_BINDINGS
              : isDirectCall
                ? undefined
                : (callArgs[0] as Record<string, unknown>),
          );
          const propertyValue = Reflect.get(Object(serviceValue), property);

          if (!isDirectCall) {
            return propertyValue;
          }

          return Reflect.apply(
            propertyValue as (...args: unknown[]) => unknown,
            Object(serviceValue),
            callArgs,
          );
        };

        const propertyHelper = new Proxy(propertyHelperFn, {
          get(fnTarget, nestedProperty, fnReceiver) {
            if (typeof nestedProperty !== 'string') {
              return Reflect.get(fnTarget, nestedProperty, fnReceiver);
            }
            if (isReservedShortcutProperty(nestedProperty)) {
              return Reflect.get(fnTarget, nestedProperty, fnReceiver);
            }
            if (!nestedPropertyHelpers.has(nestedProperty)) {
              nestedPropertyHelpers.set(
                nestedProperty,
                createInjectPathShortcut(
                  definition,
                  property,
                  [nestedProperty],
                  injectMarker,
                ),
              );
            }
            return nestedPropertyHelpers.get(nestedProperty);
          },
        });

        const metaData = getMetaData();

        if (metaData) {
          attachServiceRuntimeMeta(propertyHelper, metaData);
        }

        propertyHelpers.set(property, propertyHelper);
      }

      return propertyHelpers.get(property);
    },
  });

  return outerProxy;
}

/**
 * What a yield shortcut hands back for the member it designates: a reactive
 * reader is read, so `yield* View.todos.status()` is the status itself, and a
 * binding gets a plain value. Any other member (object, method) is returned:
 * a `craftMethod` is named like a reader, but reading it would run it, which
 * only a call of the shortcut may do.
 */
function* readShortcutMember(
  member: unknown,
): Generator<unknown, unknown, unknown> {
  if (
    !isYieldableValue(member) ||
    isCraftMethod(member) ||
    typeof (member as { type?: unknown }).type === 'string'
  ) {
    return member;
  }
  // Some readers (those of a selected item) answer a plain call with the value
  // itself rather than a generator to drive.
  const read = (member as unknown as () => unknown)();
  return isGenerator(read) ? yield* read : read;
}

/**
 * Whether a member is something to call: a `craftMethod`, or a function that is
 * neither a reactive reader nor a raw signal, both of which a shortcut hands
 * back to be read. A shortcut call runs it, wherever it is yielded: exposing a
 * method is `craftExpose('save', View.save)`, without the call.
 */
function isShortcutMethod(member: unknown): boolean {
  if (typeof member !== 'function') return false;
  if (isCraftMethod(member)) return true;
  if (isYieldableValue(member)) return false;
  const isSignal =
    isCraftSignal(member) ||
    'set' in member ||
    'update' in member ||
    Object.getOwnPropertySymbols(member).some(
      (symbol) => symbol.description === 'SIGNAL',
    );
  return !isSignal;
}

/**
 * Names a shortcut node keeps for itself. Every other name below a shortcut is
 * a member of the service output, however deep, so `name`, `length` or
 * `prototype` of the underlying function must not shadow a member. `call` is
 * not reserved either: it is how a method-based query is triggered
 * (`View.userQuery.call(params)`).
 */
function isReservedShortcutProperty(property: string): boolean {
  return (
    property === 'then' ||
    property === 'apply' ||
    property === 'bind' ||
    property === 'toString'
  );
}

/** One step of a shortcut chain: a member name, or a call of what precedes. */
type ShortcutStep = string | { readonly args: readonly unknown[] };

/**
 * Resolves the service and walks `steps` from its `key` member.
 *
 * A call step runs the member it follows, with its arguments, when there are
 * any or when the member is a method and `callMethods` allows it; otherwise
 * the member is read. What the call returns is where the next steps continue,
 * which is what lets `store.users.selectOrCreate(id).isLoading()` be one chain.
 */
function* driveShortcut(
  definition: ConcreteRuntimeDefinition,
  key: string,
  steps: readonly ShortcutStep[],
  bindings: Record<string, unknown> | typeof OMIT_INPUTS_BINDINGS | undefined,
  callMethods: boolean,
): Generator<unknown, unknown, unknown> {
  const last = steps[steps.length - 1];
  // Only a plain `a.b.c()` read exposes its member, under its own name.
  const isPlainRead =
    last !== undefined &&
    typeof last !== 'string' &&
    last.args.length === 0 &&
    steps.slice(0, -1).every((step) => typeof step === 'string');
  const serviceValue = (yield createYieldRequest(
    definition,
    bindings,
    isPlainRead ? key : undefined,
    isPlainRead ? (steps.slice(0, -1) as string[]) : [],
  )) as unknown;

  let owner: unknown = serviceValue;
  let value: unknown = Reflect.get(Object(serviceValue), key);
  for (const step of steps) {
    if (typeof step === 'string') {
      owner = value;
      value = Reflect.get(Object(value), step);
      continue;
    }
    if (step.args.length > 0 || (callMethods && isShortcutMethod(value))) {
      const result = Reflect.apply(
        value as (...callArgs: unknown[]) => unknown,
        Object(owner),
        [...step.args],
      );
      value = isGeneratorFunction(result)
        ? yield* result()
        : isGenerator(result)
          ? yield* result
          : result;
      owner = value;
    } else {
      value = yield* readShortcutMember(value);
    }
  }
  return value;
}

/** Members a generator keeps for itself; every other name continues the chain. */
function isReservedGeneratorProperty(property: string): boolean {
  return (
    property === 'next' ||
    property === 'return' ||
    property === 'throw' ||
    property === 'then' ||
    property === 'constructor'
  );
}

/**
 * The result of calling a shortcut: a generator that, driven, runs the chain,
 * and that also answers member reads with the shortcut one step further.
 */
function createShortcutCall(
  definition: ConcreteRuntimeDefinition,
  key: string,
  steps: readonly ShortcutStep[],
): unknown {
  const children = new Map<string, unknown>();
  const generator = driveShortcut(definition, key, steps, undefined, true);

  return new Proxy(generator, {
    get(target, property) {
      if (
        typeof property !== 'string' ||
        isReservedGeneratorProperty(property)
      ) {
        const member = Reflect.get(target, property, target) as unknown;
        return typeof member === 'function' ? member.bind(target) : member;
      }
      if (!children.has(property)) {
        children.set(
          property,
          createYieldPathShortcut(definition, key, [...steps, property]),
        );
      }
      return children.get(property);
    },
  });
}

/**
 * A shortcut below `service.<key>`: a generator function that resolves the
 * service, walks `steps` from the `key` member and returns what it finds (or
 * calls it, when given arguments). Each further property read yields the
 * shortcut one level deeper, and so does each call, so the chain is as long as
 * the output and the calls on it.
 */
function createYieldPathShortcut(
  definition: ConcreteRuntimeDefinition,
  key: string,
  steps: readonly ShortcutStep[],
): unknown {
  const children = new Map<string, unknown>();

  // A service with public inputs takes its bindings as the first argument: no
  // call arguments to chain there.
  const withBindings = function* (...args: unknown[]) {
    return yield* driveShortcut(
      definition,
      key,
      steps,
      args[0] as
        | Record<string, unknown>
        | typeof OMIT_INPUTS_BINDINGS
        | undefined,
      false,
    );
  };

  return new Proxy(withBindings, {
    apply(target, thisArg, args) {
      if (definition.hasPublicInput || args[0] === OMIT_INPUTS_BINDINGS) {
        return Reflect.apply(target, thisArg, args);
      }
      return createShortcutCall(definition, key, [...steps, { args }]);
    },
    get(target, property, receiver) {
      if (property === YIELDABLE_VALUE) {
        const named = [...steps]
          .reverse()
          .find((step) => typeof step === 'string');
        return named ?? key;
      }
      if (property === SHORTCUT_MEMBER) {
        return () => driveShortcut(definition, key, steps, undefined, true);
      }
      if (
        typeof property !== 'string' ||
        isReservedShortcutProperty(property) ||
        property === 'constructor'
      ) {
        return Reflect.get(target, property, receiver);
      }
      if (!children.has(property)) {
        children.set(
          property,
          createYieldPathShortcut(definition, key, [...steps, property]),
        );
      }
      return children.get(property);
    },
  });
}

/** Inject-context counterpart of {@link createYieldPathShortcut}. */
function createInjectPathShortcut(
  definition: ConcreteRuntimeDefinition,
  key: string,
  path: readonly string[],
  injectMarker: () => void,
): unknown {
  const children = new Map<string, unknown>();

  const shortcut = (...args: unknown[]) => {
    assertInInjectionContext(injectMarker);
    const isDirectCall = args.length > 0 && !definition.hasPublicInput;
    const serviceValue = resolveConcreteService(
      definition,
      inject(Injector),
      args[0] === OMIT_INPUTS_BINDINGS
        ? OMIT_INPUTS_BINDINGS
        : isDirectCall
          ? undefined
          : (args[0] as Record<string, unknown>),
    );

    let owner: unknown = serviceValue;
    let value: unknown = Reflect.get(Object(serviceValue), key);
    for (const segment of path) {
      owner = value;
      value = Reflect.get(Object(value), segment);
    }
    if (!isDirectCall) return value;

    return Reflect.apply(
      value as (...callArgs: unknown[]) => unknown,
      Object(owner),
      args,
    );
  };

  return new Proxy(shortcut, {
    get(target, property, receiver) {
      if (
        typeof property !== 'string' ||
        isReservedShortcutProperty(property)
      ) {
        return Reflect.get(target, property, receiver);
      }
      if (!children.has(property)) {
        children.set(
          property,
          createInjectPathShortcut(
            definition,
            key,
            [...path, property],
            injectMarker,
          ),
        );
      }
      return children.get(property);
    },
  });
}

function createHelper(
  definition: ConcreteRuntimeDefinition,
  getMetaData: () => InternalServiceMetaData | undefined,
) {
  const propertyHelpers = new Map<string, unknown>();
  let omitInputsProxy: object | null = null;

  const toYieldHelper = function* (
    bindings?: Record<string, unknown>,
    expose?: RuntimeExposureSelector,
  ) {
    const serviceValue = (yield createYieldRequest(
      definition,
      bindings,
      uncapitalizeFirst(definition.name),
    )) as unknown;

    if (!expose) {
      return serviceValue;
    }

    return (yield* exposeServiceValue(serviceValue, expose)) as unknown;
  };

  const outerProxy = new Proxy(toYieldHelper, {
    get(target, property, receiver) {
      if (typeof property !== 'string') {
        return Reflect.get(target, property, receiver);
      }

      if (property === 'then' || property in target) {
        return Reflect.get(target, property, receiver);
      }

      if (property === 'OmitInputs') {
        if (!omitInputsProxy) {
          omitInputsProxy = new Proxy({} as object, {
            get(_, subProp, subReceiver) {
              return wrapOmitInputsHelper(
                Reflect.get(outerProxy, subProp, subReceiver),
              );
            },
          });
        }
        return omitInputsProxy;
      }

      if (!propertyHelpers.has(property)) {
        const nestedPropertyHelpers = new Map<string, unknown>();

        const propertyHelperFn = function* (...args: unknown[]) {
          const omitInputs = args[0] === OMIT_INPUTS_BINDINGS;
          const callArgs = omitInputs ? args.slice(1) : args;
          const isDirectCall =
            callArgs.length > 0 && !definition.hasPublicInput;
          const serviceValue = (yield createYieldRequest(
            definition,
            omitInputs
              ? OMIT_INPUTS_BINDINGS
              : isDirectCall
                ? undefined
                : (callArgs[0] as Record<string, unknown>),
            property,
          )) as unknown;
          const propertyValue = Reflect.get(Object(serviceValue), property);

          // A method is called even without arguments (the bindings, when
          // given, only pick the instance); any other member is read.
          if (!isDirectCall && !isShortcutMethod(propertyValue)) {
            return yield* readShortcutMember(propertyValue);
          }

          const result = Reflect.apply(
            propertyValue as (...args: unknown[]) => unknown,
            Object(serviceValue),
            isDirectCall ? callArgs : [],
          );
          return isGeneratorFunction(result)
            ? yield* result()
            : isGenerator(result)
              ? yield* result
              : result;
        };

        const propertyHelper = new Proxy(propertyHelperFn, {
          get(fnTarget, nestedProperty, fnReceiver) {
            // The shortcut is named after its member, which is what lets
            // `ifNode(View.isOpen, …)` take it as a named condition.
            if (nestedProperty === YIELDABLE_VALUE) return property;
            if (nestedProperty === SHORTCUT_MEMBER) {
              return () =>
                driveShortcut(definition, property, [], undefined, true);
            }
            if (typeof nestedProperty !== 'string') {
              return Reflect.get(fnTarget, nestedProperty, fnReceiver);
            }
            if (isReservedShortcutProperty(nestedProperty)) {
              return Reflect.get(fnTarget, nestedProperty, fnReceiver);
            }
            if (!nestedPropertyHelpers.has(nestedProperty)) {
              nestedPropertyHelpers.set(
                nestedProperty,
                createYieldPathShortcut(definition, property, [nestedProperty]),
              );
            }
            return nestedPropertyHelpers.get(nestedProperty);
          },
        });

        const metaData = getMetaData();

        if (metaData) {
          attachServiceRuntimeMeta(propertyHelper, metaData);
        }

        propertyHelpers.set(property, propertyHelper);
      }

      return propertyHelpers.get(property);
    },
  });

  return outerProxy;
}

function createServiceRequirement<Contract, Name extends string>(
  name: Name,
  token: object,
): ServiceRequirement<Contract, Name> {
  return {
    [SERVICE_REQUIREMENT_MARKER]: true,
    name,
    [SERVICE_REQUIREMENT_TOKEN]: token,
  };
}

function createServiceMetaData(config: {
  name: string;
  providedIn: ConcreteServiceScope;
  inject: (...args: any[]) => unknown;
  provide?: (...args: any[]) => CraftServiceProvider;
  runtimeDefinition: ConcreteRuntimeDefinition;
}): InternalServiceMetaData {
  const metaData: Record<string, unknown> = {
    kind: 'service-meta-data',
    name: config.name,
    providedIn: config.providedIn,
    browserBoundary: config.runtimeDefinition.browserBoundary,
    appStart: config.runtimeDefinition.appStart,
    inject: config.inject,
    usesProvidedInput: config.runtimeDefinition.hasProvidedInput,
  };

  if (config.provide) {
    metaData['provide'] = config.provide;
  }

  Object.defineProperty(metaData, SERVICE_RUNTIME_DEFINITION, {
    value: config.runtimeDefinition,
    enumerable: false,
    configurable: false,
  });

  Object.defineProperty(metaData, SERVICE_RUNTIME_META, {
    value: metaData,
    enumerable: false,
    configurable: false,
  });

  Object.defineProperty(metaData, SERVICE_RUNTIME_META_GLOBAL, {
    value: metaData,
    enumerable: false,
    configurable: false,
  });

  return metaData as InternalServiceMetaData;
}

function attachServiceRuntimeMeta(
  helper: unknown,
  metaData: InternalServiceMetaData,
) {
  if (typeof helper !== 'function') {
    return;
  }

  Object.defineProperty(helper, SERVICE_RUNTIME_META, {
    value: metaData,
    enumerable: false,
    configurable: false,
  });

  Object.defineProperty(helper, SERVICE_RUNTIME_META_GLOBAL, {
    value: metaData,
    enumerable: false,
    configurable: false,
  });
}

/**
 * The injection token a concrete service is stored under, when it has one.
 *
 * Scopes that never reach the injector (a `function` service, a global one)
 * answer `undefined`: there is nothing to re-provide for them.
 */
export function ɵgetServiceInjectionToken(
  target: unknown,
): InjectionToken<unknown> | undefined {
  const metaData = getServiceMetaData(target) as InternalServiceMetaData;
  return metaData[SERVICE_RUNTIME_DEFINITION]?.token as
    | InjectionToken<unknown>
    | undefined;
}

export function getServiceMetaData(target: unknown): AnyServiceMetaData {
  if (isServiceMetaData(target)) {
    return target;
  }

  if (typeof target === 'object' || typeof target === 'function') {
    const runtimeMeta = (Reflect.get(target as object, SERVICE_RUNTIME_META) ??
      Reflect.get(target as object, SERVICE_RUNTIME_META_GLOBAL)) as
      | InternalServiceMetaData
      | undefined;

    if (runtimeMeta) {
      return runtimeMeta;
    }
  }

  throw new Error(
    'Expected a craftService helper or a service metadata object.',
  );
}

function isServiceMetaData(value: unknown): value is InternalServiceMetaData {
  return (
    typeof value === 'object' &&
    value !== null &&
    Reflect.get(value, 'kind') === 'service-meta-data' &&
    SERVICE_RUNTIME_DEFINITION in value
  );
}

/**
 * @internal The provider `provide<Name>(value)` builds, for a value that
 * differs from one injector to the next: `read` answers it from the injector
 * that resolves the service, so the same provider serves every one of them.
 */
export function ɵprovideServiceReading(
  metaData: unknown,
  read: (injector: Injector) => unknown,
): CraftServiceProvider {
  return createProviders(
    (metaData as { [SERVICE_RUNTIME_DEFINITION]: ConcreteRuntimeDefinition })[
      SERVICE_RUNTIME_DEFINITION
    ],
    [],
    read,
  ) as CraftServiceProvider;
}

function createProviders(
  definition: ConcreteRuntimeDefinition,
  providedArgs: unknown[] = [],
  readProvided?: (injector: Injector) => unknown,
): NamedBrandedServiceProvider<string, RequirementScope, unknown> {
  const concreteToken = definition.token;

  if (!concreteToken) {
    throw new Error(
      `craftService("${definition.name}") cannot create providers for scope "${definition.providedIn}".`,
    );
  }

  const providers: CraftServiceProvider[] = [];
  const staticConfig = normalizeProvidedConfig(providedArgs);

  const concreteProviders: Provider[] = [
    {
      provide: concreteToken,
      ɵcraftCollection: definition.collection,
      useFactory: () => {
        const injector = inject(Injector);
        const providedConfig = readProvided
          ? readProvided(injector)
          : staticConfig;
        const override = getServiceRuntimeOverride(injector, definition.name);
        if (override?.kind === 'notReached') {
          throw new Error(
            `Craft service "${definition.name}" was registered as notReached but was resolved.`,
          );
        }
        if (override?.kind === 'useValue') return override.value;
        if (override?.kind === 'instantiate') {
          if (override.instance === undefined) {
            override.instance = createConcreteServiceInstance(
              definition,
              injector,
              undefined,
              providedConfig,
            );
          }
          return override.instance;
        }
        return createConcreteServiceInstance(
          definition,
          injector,
          undefined,
          providedConfig,
        );
      },
    },
  ];

  if (
    definition.requirement &&
    definition.requirement[SERVICE_REQUIREMENT_TOKEN] !== concreteToken
  ) {
    concreteProviders.push({
      provide: definition.requirement[SERVICE_REQUIREMENT_TOKEN],
      useExisting: concreteToken,
    });
  }

  providers.push(concreteProviders);

  const brandedProviders = providers as NamedBrandedServiceProvider<
    string,
    RequirementScope,
    unknown
  >;

  Object.defineProperty(brandedProviders, CRAFT_SERVICE_PROVIDER_BRAND, {
    value: {
      name: definition.name,
      providedIn: definition.providedIn,
      output: undefined,
      yielded: undefined,
    },
    enumerable: false,
    configurable: false,
  });

  return brandedProviders;
}

function normalizeProvidedConfig(providedArgs: unknown[]): unknown {
  if (providedArgs.length === 0) {
    return undefined;
  }

  return providedArgs.length === 1 ? providedArgs[0] : providedArgs;
}

function createYieldRequest(
  definition: ConcreteRuntimeDefinition,
  bindings?: ConcreteServiceBindings,
  exposedAs?: string,
  path: readonly string[] = [],
): ServiceYieldRequest<
  ConcreteServiceScope,
  unknown,
  AnyServiceTrackingMetadata,
  any,
  any
> {
  return {
    [SERVICE_YIELD_REQUEST_MARKER]: true,
    name: definition.name,
    ...(exposedAs
      ? {
          exposure: {
            // A deep shortcut exposes the member it designates, under that
            // member's own name.
            name: path.length > 0 ? path[path.length - 1] : exposedAs,
            ...(path.length === 0 &&
            exposedAs === uncapitalizeFirst(definition.name)
              ? { internal: true }
              : {}),
            resolve: (service: unknown) => {
              if (
                path.length === 0 &&
                exposedAs === uncapitalizeFirst(definition.name)
              ) {
                return service;
              }
              const member = [exposedAs, ...path].reduce<unknown>(
                (owner, segment) => Reflect.get(Object(owner), segment),
                service,
              );
              // A method reached through a shortcut is called, not exposed.
              return isShortcutMethod(member) ? NOT_EXPOSED : member;
            },
          },
        }
      : {}),
    providedIn: definition.providedIn,
    resolve: (injector, hostScope) => {
      assertDependencyScope(hostScope, definition.providedIn, definition.name);
      return resolveConcreteService(definition, injector, bindings);
    },
  };
}

function uncapitalizeFirst(value: string): string {
  return value.length === 0 ? value : value[0].toLowerCase() + value.slice(1);
}

/** Internal absence marker; provided null and undefined remain service values. */
export const ɵSERVICE_NOT_FOUND = Symbol('CraftService.notFound');

/** Resolve an internal DI slot without throwing when only that slot is absent. */
export function ɵresolveOptionalService(
  reference: unknown,
  injector: Injector = inject(Injector),
): unknown {
  const metadata = getServiceMetaData(reference) as InternalServiceMetaData;
  return resolveConcreteService(
    metadata[SERVICE_RUNTIME_DEFINITION],
    injector,
    undefined,
    ɵSERVICE_NOT_FOUND,
  );
}

/** @internal What {@link ɵreadServiceMember} answers when the caller must read the generic way. */
export const ɵSERVICE_MEMBER_UNREAD = Symbol('CraftService.memberUnread');

// Services an injector resolved for direct member reads; null when the
// injector wraps service resolution, which then always takes the generic way.
const resolvedForReads = new WeakMap<
  Injector,
  Map<ConcreteRuntimeDefinition, unknown> | null
>();

/**
 * @internal `yield* Service.member()` without the generator protocol, for
 * code the build compiled: the service is resolved once per injector (it is
 * the same instance each time: neither a function-scoped service nor an
 * injector with service-yield wrappers takes this way), then its member is
 * returned without invoking it. The caller drives readable members once in
 * its binding context. Methods and references not owned by Craft answer
 * {@link ɵSERVICE_MEMBER_UNREAD} without probing their properties.
 */
export function ɵreadServiceMember(
  reference: unknown,
  key: string,
  injector: Injector,
): unknown {
  if (
    (typeof reference !== 'function' && typeof reference !== 'object') ||
    reference === null
  )
    return ɵSERVICE_MEMBER_UNREAD;
  const definition = definitionByReference.get(reference);
  if (!definition || definition.providedIn === 'function')
    return ɵSERVICE_MEMBER_UNREAD;
  let resolved = resolvedForReads.get(injector);
  if (resolved === undefined) {
    resolved =
      injector.get(SERVICE_YIELD_WRAPPER as never, [] as readonly unknown[])
        .length === 0
        ? new Map()
        : null;
    resolvedForReads.set(injector, resolved);
  }
  if (resolved === null) return ɵSERVICE_MEMBER_UNREAD;
  let service = resolved.get(definition);
  if (service === undefined && !resolved.has(definition)) {
    const found = definition;
    service = injector.run(() => resolveConcreteService(found, injector));
    resolved.set(definition, service);
  }
  const member = Reflect.get(Object(service), key);
  if (isShortcutMethod(member)) return ɵSERVICE_MEMBER_UNREAD;
  return member;
}

function resolveConcreteService(
  definition: ConcreteRuntimeDefinition,
  injector: Injector,
  bindings?: ConcreteServiceBindings,
  notFoundValue?: typeof ɵSERVICE_NOT_FOUND,
): unknown {
  const serviceOverride = getServiceRuntimeOverride(injector, definition.name);

  if (serviceOverride) {
    if (serviceOverride.kind === 'notReached') {
      throw new Error(
        `Craft service "${definition.name}" was registered as notReached but was resolved.`,
      );
    }
    if (serviceOverride.kind === 'useValue') {
      return trackResolvedService(
        definition,
        injector,
        markNamedReactiveProperties(serviceOverride.value),
      );
    }

    if (
      bindings !== undefined &&
      bindings !== OMIT_INPUTS_BINDINGS &&
      definition.initialBindings === undefined
    ) {
      definition.initialBindings = bindings;
    }

    if (serviceOverride.instance === undefined) {
      serviceOverride.instance = createConcreteServiceInstance(
        definition,
        injector,
        bindings,
        undefined,
      );
    }

    return trackResolvedService(
      definition,
      injector,
      markNamedReactiveProperties(serviceOverride.instance),
    );
  }

  if (definition.providedIn === 'function') {
    return trackResolvedService(
      definition,
      injector,
      markNamedReactiveProperties(
        createConcreteServiceInstance(definition, injector, bindings),
      ),
    );
  }

  if (
    bindings !== undefined &&
    bindings !== OMIT_INPUTS_BINDINGS &&
    definition.initialBindings === undefined
  ) {
    definition.initialBindings = bindings;
  }

  // Hand this call's inputs to the provider for the duration of resolution.
  // Supplying a fallback avoids constructing an error for an absent token;
  // provider and dependency failures still propagate through injector.get.
  const value = withPendingServiceBindings(
    definition.name,
    bindings === OMIT_INPUTS_BINDINGS
      ? undefined
      : (bindings as Record<string, unknown> | undefined),
    () =>
      notFoundValue === undefined
        ? injector.get(definition.token as object)
        : injector.get(definition.token as object, notFoundValue),
  );
  if (value === ɵSERVICE_NOT_FOUND) return value;
  return trackResolvedService(
    definition,
    injector,
    markNamedReactiveProperties(value),
  );
}

const PENDING_SERVICE_BINDINGS = new Map<string, Record<string, unknown>>();

function withPendingServiceBindings<Result>(
  name: string,
  bindings: Record<string, unknown> | undefined,
  resolve: () => Result,
): Result {
  if (bindings === undefined) {
    return resolve();
  }

  const previous = PENDING_SERVICE_BINDINGS.get(name);
  PENDING_SERVICE_BINDINGS.set(name, bindings);
  try {
    return resolve();
  } finally {
    if (previous === undefined) {
      PENDING_SERVICE_BINDINGS.delete(name);
    } else {
      PENDING_SERVICE_BINDINGS.set(name, previous);
    }
  }
}

function trackResolvedService(
  definition: ConcreteRuntimeDefinition,
  injector: Injector,
  value: unknown,
): unknown {
  const hostTags = injector.get(ɵHOST_TAG_LIST, []);
  registerResolvedService(
    injector,
    definition.name,
    value,
    hostTags[hostTags.length - 1] ?? `service:${definition.name}`,
    definition.providedIn,
  );
  return value;
}

function getServiceRuntimeOverride(
  injector: Injector,
  serviceName: string,
): ServiceRuntimeOverride | undefined {
  return injector.get(SERVICE_RUNTIME_OVERRIDES).get(serviceName);
}

/**
 * Builds a service. A global one is built outside every flow: it lives as
 * long as the app, so what it starts (a countdown, a polling) is not the
 * work of the click or the navigation that happened to need it first.
 */
function createConcreteServiceInstance(
  definition: ConcreteRuntimeDefinition,
  injector: Injector,
  bindingsOverride?: ConcreteServiceBindings,
  providedConfig?: unknown,
): unknown {
  return definition.providedIn === 'global'
    ? ɵrunOutsideScheduledContext(() =>
        buildConcreteServiceInstance(
          definition,
          injector,
          bindingsOverride,
          providedConfig,
        ),
      )
    : buildConcreteServiceInstance(
        definition,
        injector,
        bindingsOverride,
        providedConfig,
      );
}

function buildConcreteServiceInstance(
  definition: ConcreteRuntimeDefinition,
  injector: Injector,
  bindingsOverride?: ConcreteServiceBindings,
  providedConfig?: unknown,
): unknown {
  const scopedInjector = ɵcreateHostTaggedInjector(
    injector,
    `service:${definition.name}`,
    definition.providers ?? [],
    {
      instanced:
        definition.providedIn === 'function' ||
        definition.providedIn === 'toProvide',
    },
  );

  return runInInjectionContext(scopedInjector, () =>
    scopedInjector.run(() => {
      const omitInputs = bindingsOverride === OMIT_INPUTS_BINDINGS;
      const bindings = omitInputs
        ? {}
        : (bindingsOverride ??
          PENDING_SERVICE_BINDINGS.get(definition.name) ??
          definition.initialBindings ??
          {});
      const inputs = createInputProxy(
        bindings,
        providedConfig,
        omitInputs,
        definition.name,
      );
      const wrappedFactory = injectFnWrapper()(definition.factory);
      const result =
        definition.factory.length > 0
          ? wrappedFactory(inputs)
          : wrappedFactory();

      const autoExpose = definition.exposure === 'auto';

      if (!isGenerator(result)) {
        if (autoExpose) {
          throw new Error(
            `craftService("${definition.name}") needs a generator factory (function* () { ... }): its API is the named primitives it yields. See the craft-ts/no-craft-service-return rule.`,
          );
        }
        return result;
      }

      const exposed: Record<string, unknown> = {};
      const resolved = runCraftGenerator({
        iterator: result,
        injector: scopedInjector,
        hostScope: definition.providedIn,
        collectExposed: autoExpose
          ? { record: exposed, owner: `craftService("${definition.name}")` }
          : undefined,
        invalidYieldErrorMessage:
          'craftService generators can only yield craftService dependencies, exposed dependency helpers, or onAppStart(...).',
        multipleAppStartErrorMessage:
          'craftService generators can only declare onAppStart(...) once.',
        createAppStartHook: (run) => () =>
          runAppStartCallback(run, scopedInjector, definition.providedIn),
        reactiveReader: {
          name: definition.name,
          primitive: 'craftService',
          path: `service:${definition.name}`,
        },
      });

      if (autoExpose && resolved.value !== undefined) {
        throw new Error(
          `craftService("${definition.name}") returned a value, but a craftService cannot return: its API is the named primitives it yields. Remove the return (wrap what must stay internal in craftPrivate(...)); see the craft-ts/no-craft-service-return rule.`,
        );
      }

      const instance = autoExpose ? exposed : resolved.value;

      if (resolved.appStartHook) {
        if (!definition.appStart) {
          throw new Error(
            `craftService("${definition.name}") used onAppStart(...) without enabling appStart: true.`,
          );
        }

        definition.appStartHooks.set(instance, resolved.appStartHook);
      }

      return instance;
    }),
  );
}

function runAppStartCallback(
  run: () => AppStartResult | Generator<unknown, AppStartResult, unknown>,
  injector: Injector,
  hostScope: ConcreteServiceScope,
): AppStartResult {
  const result = run();

  if (!isGenerator(result)) {
    return result;
  }

  return runCraftGenerator({
    iterator: result,
    injector,
    hostScope,
    invalidYieldErrorMessage:
      'craftService generators can only yield craftService dependencies, exposed dependency helpers, or onAppStart(...).',
    multipleAppStartErrorMessage:
      'craftService generators can only declare onAppStart(...) once.',
    onAppStartNotSupportedErrorMessage:
      'onAppStart(...) generator callbacks cannot declare onAppStart(...) recursively.',
    reactiveReader: {
      name: `${hostScope}:appStart`,
      primitive: 'craftService',
      path: `appStart:${hostScope}`,
    },
  }).value as AppStartResult;
}

function createInputProxy(
  bindings: Record<string, unknown>,
  providedConfig?: unknown,
  allowMissing = false,
  serviceName = 'craftService',
): Record<string, unknown> {
  const resolvedBindings =
    providedConfig === undefined
      ? bindings
      : {
          ...bindings,
          [SERVICE_PROVIDED_INPUT_KEY]: providedConfig,
        };

  return new Proxy<Record<string, unknown>>({} as Record<string, unknown>, {
    get(_target, property) {
      if (typeof property !== 'string') {
        return undefined;
      }

      if (!Object.prototype.hasOwnProperty.call(resolvedBindings, property)) {
        if (allowMissing || property === SERVICE_PROVIDED_INPUT_KEY) {
          return undefined;
        }
        throw new Error(`Inputs Error, ${property} is not provided`);
      }

      const value = resolvedBindings[property];

      if (value === PROVIDED_ELSEWHERE) {
        throw new Error(`Inputs Error, ${property} is not provided`);
      }

      // `$provided` is service configuration, not a reactive service input.
      // In particular, host components are callable values and must reach
      // their provider factory unchanged.
      if (property === SERVICE_PROVIDED_INPUT_KEY) {
        return value;
      }

      return isReactiveServiceInput(value)
        ? createServiceInputReader(value, serviceName, property)
        : value;
    },
  });
}

const CONTENT_DECLARATION_CONTEXT = Symbol.for(
  'craft-content-declaration-context',
);

/** Projected content is a renderer, never a value to read: leave it alone. */
function isProjectedContent(value: unknown): boolean {
  return (
    (typeof value === 'function' || typeof value === 'object') &&
    value !== null &&
    CONTENT_DECLARATION_CONTEXT in (value as object)
  );
}

function isReactiveServiceInput(value: unknown): boolean {
  if (isProjectedContent(value)) {
    return false;
  }

  return (
    isSignal(value) ||
    isYieldableReactiveValue(value) ||
    typeof value === 'function'
  );
}

function createServiceInputReader(
  source: unknown,
  serviceName: string,
  property: string,
): ServiceInputReader {
  const reactiveSource =
    isSignal(source) && !isYieldableReactiveValue(source)
      ? createYieldableReactiveValue(source, `${serviceName}.${property}`, {
          primitive: 'craftService',
          path: `service:${serviceName}.input.${property}`,
        })
      : source;

  const reader = markYieldableMethod((...args: unknown[]) => {
    const value =
      typeof reactiveSource === 'function'
        ? (reactiveSource as (...args: unknown[]) => unknown)(...args)
        : reactiveSource;

    return isGenerator(value)
      ? value
      : yieldableInvocation<unknown, unknown>(value);
  }) as unknown as ServiceInputReader;

  Object.defineProperty(reader, SERVICE_INPUT_SOURCE, {
    value: reactiveSource,
    enumerable: false,
    configurable: false,
  });

  return reader;
}

function resolveExposedService(
  serviceValue: unknown,
  expose: RuntimeExposureSelector,
  injector: Injector,
  hostScope: ConcreteServiceScope,
): unknown {
  const exposure = expose(createExposureTokens(serviceValue));
  const resolvedExposure = isGenerator(exposure)
    ? runCraftGenerator({
        iterator: exposure,
        injector,
        hostScope,
        invalidYieldErrorMessage:
          'craftService generators can only yield craftService dependencies, exposed dependency helpers, or onAppStart(...).',
        multipleAppStartErrorMessage:
          'craftService generators can only declare onAppStart(...) once.',
      }).value
    : exposure;

  return createExposedServiceValue(resolvedExposure);
}

function* exposeServiceValue(
  serviceValue: unknown,
  expose: RuntimeExposureSelector,
): Generator<
  ServiceDependencyAccessRequest<string, unknown>,
  unknown,
  unknown
> {
  const exposure = expose(createExposureTokens(serviceValue));
  const resolvedExposure = isGenerator(exposure)
    ? yield* exposure as Generator<
        ServiceDependencyAccessRequest<string, unknown>,
        unknown,
        unknown
      >
    : exposure;

  return createExposedServiceValue(resolvedExposure);
}

type RuntimeExposureToken = (() => Generator<
  ServiceDependencyAccessRequest<string, unknown>,
  unknown,
  unknown
>) & {
  [SERVICE_EXPOSURE_TOKEN_MARKER]: {
    key: string;
    resolve: () => unknown;
  };
};

function createExposureTokens(
  serviceValue: unknown,
): Record<string, RuntimeExposureToken> {
  return new Proxy(
    {},
    {
      get(_target, property) {
        if (typeof property !== 'string') {
          return undefined;
        }

        if (
          property === SERVICE_ROOT_EXPOSURE_KEY &&
          typeof serviceValue !== 'function'
        ) {
          return undefined;
        }

        return createExposureToken(serviceValue, property);
      },
    },
  );
}

function createExposureToken(
  serviceValue: unknown,
  key: string,
): RuntimeExposureToken {
  const resolve =
    key === SERVICE_ROOT_EXPOSURE_KEY
      ? () => serviceValue
      : () => Reflect.get(Object(serviceValue), key);
  const token = function* () {
    return (yield createDependencyAccessRequest(key, resolve)) as unknown;
  } as RuntimeExposureToken;

  Object.defineProperty(token, SERVICE_EXPOSURE_TOKEN_MARKER, {
    value: {
      key,
      resolve,
    },
    enumerable: false,
    configurable: false,
  });

  return token;
}

function createDependencyAccessRequest(
  key: string,
  resolve: () => unknown,
): ServiceDependencyAccessRequest<string, unknown> {
  return {
    [SERVICE_DEPENDENCY_ACCESS_MARKER]: true,
    key,
    resolve,
  };
}

function createAppStartRequest<Yielded>(
  run: () => AppStartResult | Generator<Yielded, AppStartResult, unknown>,
): ServiceAppStartRequest<Yielded> {
  return {
    [SERVICE_APP_START_REQUEST_MARKER]: true,
    run,
  };
}

export function runServiceAppStart(
  reference: ServiceReference,
  serviceValue: unknown,
): AppStartResult {
  const metaData = getServiceMetaData(reference) as InternalServiceMetaData;
  const definition = metaData[SERVICE_RUNTIME_DEFINITION];

  if (!definition.appStart) {
    throw new Error(
      `craftService("${definition.name}") is not configured with appStart: true.`,
    );
  }

  if (definition.startedAppStartServices.has(serviceValue)) {
    return;
  }

  const hook = definition.appStartHooks.get(serviceValue);

  if (!hook) {
    throw new Error(
      `craftService("${definition.name}") is configured with appStart: true but did not declare onAppStart(...).`,
    );
  }

  definition.startedAppStartServices.add(serviceValue);

  return hook();
}

export function getRegisteredAppStartServices(): readonly ServiceReference[] {
  return Array.from(REGISTERED_APP_START_SERVICES.values());
}

export function getRegisteredServices(): readonly ServiceReference[] {
  return Array.from(REGISTERED_SERVICES.values());
}

type RuntimeCallable = (...args: any[]) => unknown;

type RuntimeMaterializedExposure = {
  value: unknown;
  rootCallable?: RuntimeCallable;
};

export function createExposedServiceValue(exposedValue: unknown): unknown {
  const materializedExposure = materializeExposedValue(exposedValue);
  markNamedReactiveProperties(materializedExposure.value);

  if (!materializedExposure.rootCallable) {
    return materializedExposure.value;
  }

  if (
    !isNonCallableObject(materializedExposure.value) ||
    Reflect.ownKeys(materializedExposure.value).length === 0
  ) {
    return materializedExposure.rootCallable;
  }

  return createCallableExposureProxy(
    materializedExposure.rootCallable,
    materializedExposure.value,
  );
}

function materializeExposedValue(
  exposedValue: unknown,
): RuntimeMaterializedExposure {
  if (isRuntimeExposureToken(exposedValue)) {
    const resolvedValue = exposedValue[SERVICE_EXPOSURE_TOKEN_MARKER].resolve();

    return isRootRuntimeExposureToken(exposedValue) &&
      typeof resolvedValue === 'function'
      ? {
          value: resolvedValue,
          rootCallable: resolvedValue as RuntimeCallable,
        }
      : { value: resolvedValue };
  }

  if (!isNonCallableObject(exposedValue)) {
    return { value: exposedValue };
  }

  const materialized: Record<PropertyKey, unknown> = {};
  let rootCallable: RuntimeCallable | undefined;

  for (const key of Reflect.ownKeys(exposedValue)) {
    const resolvedValue = unwrapDirectExposureToken(
      Reflect.get(exposedValue, key, exposedValue),
    );

    if (
      key === SERVICE_ROOT_EXPOSURE_KEY &&
      typeof resolvedValue === 'function'
    ) {
      rootCallable = resolvedValue as RuntimeCallable;
      continue;
    }

    materialized[key] = resolvedValue;
  }

  if (rootCallable && Reflect.ownKeys(materialized).length === 0) {
    return {
      value: rootCallable,
      rootCallable,
    };
  }

  return {
    value: materialized,
    rootCallable,
  };
}

function unwrapDirectExposureToken(value: unknown): unknown {
  return isRuntimeExposureToken(value)
    ? value[SERVICE_EXPOSURE_TOKEN_MARKER].resolve()
    : value;
}

function createCallableExposureProxy(
  serviceValue: (...args: any[]) => unknown,
  exposedValue: object,
) {
  const exposedKeys = new Set(Reflect.ownKeys(exposedValue));
  const forwardedTargetKeys = new Set<PropertyKey>(
    Reflect.ownKeys(serviceValue).filter(
      (key) =>
        typeof key === 'symbol' ||
        Reflect.getOwnPropertyDescriptor(serviceValue, key)?.configurable ===
          false,
    ),
  );

  return new Proxy(serviceValue, {
    get(target, property, receiver) {
      if (exposedKeys.has(property)) {
        return Reflect.get(exposedValue, property, exposedValue);
      }

      if (
        forwardedTargetKeys.has(property) ||
        (typeof property === 'string' && property in Function.prototype)
      ) {
        return Reflect.get(target, property, receiver);
      }

      return undefined;
    },
    has(_target, property) {
      return (
        exposedKeys.has(property) ||
        forwardedTargetKeys.has(property) ||
        (typeof property === 'string' && property in Function.prototype)
      );
    },
    ownKeys() {
      return Array.from(
        new Set([
          ...Array.from(forwardedTargetKeys),
          ...Reflect.ownKeys(exposedValue),
        ]),
      ) as Array<string | symbol>;
    },
    getOwnPropertyDescriptor(target, property) {
      if (exposedKeys.has(property)) {
        return (
          Reflect.getOwnPropertyDescriptor(exposedValue, property) ?? {
            configurable: true,
            enumerable: true,
            writable: true,
            value: Reflect.get(exposedValue, property, exposedValue),
          }
        );
      }

      if (forwardedTargetKeys.has(property)) {
        return Reflect.getOwnPropertyDescriptor(target, property);
      }

      return undefined;
    },
  });
}

function isObjectLike(value: unknown): value is object {
  return (
    (typeof value === 'object' && value !== null) || typeof value === 'function'
  );
}

function isNonCallableObject(value: unknown): value is object {
  return typeof value === 'object' && value !== null;
}

type RuntimeExposureSelector = (
  dependencies: Record<string, RuntimeExposureToken>,
) => unknown;

function isRuntimeExposureToken(value: unknown): value is RuntimeExposureToken {
  return typeof value === 'function' && SERVICE_EXPOSURE_TOKEN_MARKER in value;
}

function isRootRuntimeExposureToken(value: RuntimeExposureToken): boolean {
  return value[SERVICE_EXPOSURE_TOKEN_MARKER].key === SERVICE_ROOT_EXPOSURE_KEY;
}

function assertAbstractMarker(
  value: unknown,
): asserts value is AbstractMarker<unknown> {
  if (
    typeof value !== 'object' ||
    value === null ||
    !(ABSTRACT_SERVICE_MARKER in value)
  ) {
    throw new Error('craftService scope "abstract" expects abstract<T>().');
  }
}

function assertDependencyScope(
  hostScope: ConcreteServiceScope,
  dependencyScope: ConcreteServiceScope,
  dependencyName: string,
) {
  if (hostScope === 'global' && dependencyScope === 'toProvide') {
    throw new Error(
      `Global craftService cannot depend on toProvide craftService "${dependencyName}".`,
    );
  }
}

function factoryUsesProvidedInput(factory: AnyFactory): boolean {
  return factory.toString().includes(SERVICE_PROVIDED_INPUT_KEY);
}

function factoryUsesPublicInput(factory: AnyFactory): boolean {
  return factory.length > 0;
}

function provideFactoryUsesProvidedInput(
  provideFactory: (...args: any[]) => CraftServiceProvider,
): boolean {
  return provideFactory.length > 0;
}

function capitalize(value: string): string {
  return value ? value.charAt(0).toUpperCase() + value.slice(1) : value;
}

function toMetaDataPropertyName(value: string): string {
  return `${value
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/[\s-]+/g, '_')
    .toUpperCase()}_META_DATA`;
}

const HOST_TAG_INTERNAL_SERVICE_NAMES = new Set(['service:HostName']);

export interface CraftTrackTags {}

export type TrackTag = CraftTrackTags extends {
  Tags: readonly (infer Tag)[];
}
  ? Tag & string
  : never;

export const ɵHOST_TAG_LIST = new InjectionToken<readonly string[]>(
  'HostTagList',
  {
    providedIn: 'root',
    factory: () => [],
  },
);

export const ɵTRACK_TAGS_LIST = new InjectionToken<readonly TrackTag[]>(
  'TrackTagsList',
  {
    providedIn: 'root',
    factory: () => [] as const,
  },
);

const hostNameApi = ɵcraftValueService(
  { name: 'HostName', providedIn: 'manuallyProvidedAtRoot' },
  (inputs: { $provided: string }) => inputs.$provided,
);

export const ɵinjectHostName = hostNameApi.HOST_NAME_META_DATA.inject;
export const ɵHostName = hostNameApi.HostName;
export const ɵHOST_NAME_META_DATA = hostNameApi.HOST_NAME_META_DATA;

const ɵprovideHostNameProvider = hostNameApi.provideHostName;

const OPTIONAL_FROM_PARENT = { optional: true, skipSelf: true } as const;
const NO_HOST_TAGS: readonly string[] = [];

export function ɵprovideHostName(name: string): Provider[] {
  return [
    ɵprovideHostNameProvider(name) as Provider,
    {
      provide: ɵHOST_TAG_LIST,
      useFactory: () => {
        const parentTags =
          inject(ɵHOST_TAG_LIST, OPTIONAL_FROM_PARENT) ?? NO_HOST_TAGS;
        const id = (
          ɵinjectComponentRegister() ?? ɵfallbackComponentRegister
        ).next();

        return [...parentTags, `${name}#${id}`] as readonly string[];
      },
    },
  ];
}

export function ɵprovideTrackTags(tags: readonly TrackTag[]): Provider[] {
  return [
    {
      provide: ɵTRACK_TAGS_LIST,
      useFactory: () => {
        const parentTags =
          inject(ɵTRACK_TAGS_LIST, {
            optional: true,
            skipSelf: true,
          }) ?? [];

        return [...parentTags, ...tags] as readonly TrackTag[];
      },
    },
  ];
}

export function ɵinjectTrackTags(): readonly TrackTag[] {
  return inject(ɵTRACK_TAGS_LIST);
}

export type ɵHostTagYield = Readonly<{
  [SERVICE_YIELD_REQUEST_MARKER]: true;
  providedIn: 'function';
  resolve: (
    injector: Injector,
    hostScope: ConcreteServiceScope,
  ) => readonly string[];
}>;

export function* ɵHostTag(): Generator<
  ɵHostTagYield,
  readonly string[],
  unknown
> {
  return (yield {
    [SERVICE_YIELD_REQUEST_MARKER]: true,
    providedIn: 'function',
    resolve: (injector) => injector.get(ɵHOST_TAG_LIST),
  }) as readonly string[];
}

export type ɵTrackTagsYield = Readonly<{
  [SERVICE_YIELD_REQUEST_MARKER]: true;
  providedIn: 'function';
  resolve: (
    injector: Injector,
    hostScope: ConcreteServiceScope,
  ) => readonly TrackTag[];
}>;

export function* ɵTrackTags(): Generator<
  ɵTrackTagsYield,
  readonly TrackTag[],
  unknown
> {
  return (yield {
    [SERVICE_YIELD_REQUEST_MARKER]: true,
    providedIn: 'function',
    resolve: (injector) => injector.get(ɵTRACK_TAGS_LIST),
  }) as readonly TrackTag[];
}

/**
 * The tag list a host named under `injector` carries: the node chain's tags,
 * the tags only its environment chain knows (route-level providers shadowed by
 * a parent component providing the same token) inserted before the current
 * component's tag, then the host's own tag. Semantic order is kept: parent
 * components → route → current component → host.
 *
 * `resolveHostTag` runs after the parent tags are read, so an ordinal it draws
 * keeps the order a tagged injector would have produced. Shared by
 * `ɵcreateHostTaggedInjector` and the hosts that report tags without needing
 * a scope of their own (plain `craftEffect` bodies).
 */
export function ɵmergeHostTags(
  injector: Injector,
  resolveHostTag: () => string,
): readonly string[] {
  const ownerTags = ɵhostOwnerTags(injector);
  return [...ownerTags, resolveHostTag()];
}

/**
 * {@link ɵmergeHostTags} without the host's own tag: what every host named
 * under `injector` carries before its own. The array may be the injector's
 * tag list itself: read it, do not change it.
 */
export function ɵhostOwnerTags(injector: Injector): readonly string[] {
  const nodeTags = injector.get(ɵHOST_TAG_LIST, []);

  let envOnlyTags: readonly string[] = [];
  const associatedEnvInjector = injector.get(EnvironmentInjector, null);
  // An environment injector is its own environment: it has no other tags.
  if (associatedEnvInjector && associatedEnvInjector !== injector) {
    const envTags = associatedEnvInjector.get(ɵHOST_TAG_LIST, null) ?? [];
    if (envTags !== nodeTags) {
      envOnlyTags = envTags.filter((t) => !nodeTags.includes(t));
    }
  }

  if (envOnlyTags.length === 0) return nodeTags;
  return nodeTags.length > 0
    ? [...nodeTags.slice(0, -1), ...envOnlyTags, nodeTags[nodeTags.length - 1]]
    : envOnlyTags;
}

export function ɵcreateHostTaggedInjector(
  injector: Injector,
  hostName: string,
  extraProviders: readonly Provider[] = [],
  options: { readonly instanced?: boolean } = {},
): Injector {
  if (HOST_TAG_INTERNAL_SERVICE_NAMES.has(hostName)) {
    return injector;
  }

  let parentDestroyRef: DestroyRef | null = null;
  try {
    parentDestroyRef = inject(DestroyRef, { optional: true });
  } catch {
    // not in an injection context
  }

  // EXPERIMENT (option A): stamp the instance ordinal that provideHostName's
  // factory would have produced, which this useValue would otherwise discard.
  // A host that can exist several times at once carries which one it is, the
  // way a component tag already does. A singleton does not: a number on a host
  // there is exactly one of reads as noise, and would change every log line and
  // snapshot for nothing.
  const mergedTags = ɵmergeHostTags(injector, () =>
    options.instanced
      ? `${hostName}#${(ɵinjectComponentRegister() ?? ɵfallbackComponentRegister).next()}`
      : hostName,
  );

  const envInjector = createEnvironmentInjector(
    [
      ɵprovideHostName(hostName),
      { provide: ɵHOST_TAG_LIST, useValue: mergedTags },
      ...extraProviders,
    ],
    injector as EnvironmentInjector,
    `HostTag(${hostName})`,
  );

  const detachFromParent = parentDestroyRef?.onDestroy(() => {
    if (!envInjector.destroyed) {
      envInjector.destroy();
    }
  });
  // Short-lived effects/hosts can end before the surrounding component. Do
  // not keep their already destroyed tagged injector in its destroy callbacks.
  envInjector.get(DestroyRef).onDestroy(() => detachFromParent?.());

  return envInjector;
}

