  ['view row 3', (p) => p.click('tbody tr >> nth=2 >> .cell--actions button >> nth=0')],
  ['flag row 2', (p) => p.click('tbody tr >> nth=1 >> .cell--actions button >> nth=2')],
  ['view row 3 again', (p) => p.click('tbody tr >> nth=2 >> .cell--actions button >> nth=0')],
