  ['menu close', (p) => p.click('.user-menu__toggle')],
  ['density button', (p) => p.click('.toolbar__group >> nth=1 >> .btn >> nth=1')],
  ['reset button', (p) => p.click('.toolbar__group >> nth=1 >> .btn >> nth=0')],
