  source: string,
  filename = 'component.ts',
  options: {
    lists?: boolean;
    dom?: 'create' | 'clone';
    lean?: boolean;
    lower?: boolean;
    /** @internal Facts proved by the bundler for this module. */
    importedComponents?: readonly ImportedComponentProof[];
  } = {},
