import {
  ɵrunCraftCleanups,
  ɵdestroyCraftOwner,
  ɵbeginCraftOwnerDestruction,
} from '@craft-ts/core';
import {
  ɵIDENTITY_FN_ADAPTER,
  ɵREACTIVE_READ_OBSERVERS,
  ɵinjectTemplateTraces,
} from '@craft-ts/core';
import {
  createCompiledNodes,
  compiledItemComponent,
  compiledTemplateFor,
  leanReadScope,
  type CompiledTemplatePlan,
} from './compiled-template';
import {
  CRAFT_SERVICE_PROVIDER_BRAND,
  SERVICE_RUNTIME_OVERRIDES,
  ɵinjectCraftDomEventHooks,
  CRAFT_NODE_DIRECTIVE,
  provideCraftNodeEffectFactory,
  provideCraftFieldExceptionBoundary,
  CRAFT_FIELD_EXCEPTION_SOURCE,
  ɵcraftEffectRef,
  ɵCraftRenderEffect,
  ɵeffectOwnerTags,
  ɵeffectRegistry,
  injectFnWrapper,
  isCraftDevelopment,
  type AppSnapshotRegistry,
  type FnFactoryAdapter,
  craftLazy,
  createBrowserDomAdapter,
  registerCraftSyncTemplateFlush,
  executeYieldable,
  HOST_TAG_LIST,
  executeTemplateTrace,
  isCraftException,
  isCraftGenShortCircuit,
  isCraftNotSettled,
  ɵwithSettledReadObserver,
  type CraftSettledReadNotice,
  type CraftSettledReadObserver,
  isGeneratorFunction,
  isCraftField,
  isDeepYieldable,
  isGenerator,
  deepYieldable,
