      CAMPAIGN_ATTRS_FIXTURE: 'true',
      CAMPAIGN_COMPILER_OPTIONS: JSON.stringify({
        'attrs-no-lists': { lists: false },
      }),
    },
  },
  {
    name: 'h-lean',
    ids: three,
