        const rows = raw.filter(
          (r) => r.kind === kind && r.count === count && r.label === label,
        );
        summary.push({
          case: kind,
          count,
          label,
          ...Object.fromEntries(
            ['mount', 'ready', 'twoFrames', 'heapMiB'].map((key) => [
              key,
